// IT Essentials – Deel II: Hardwarecomponenten – 6: Optische geheugens en leesgeheugens
// v = vraag, a = antwoord, o = onderwerp (bovenaan de kaart), uitleg = extra uitleg onder het antwoord
// img = afbeelding op de voorkant (map afbeeldingen/ITdeel2les6_optisch/), imgAntwoord = afbeelding op de achterkant (optioneel)
// wit: true = witte kaart die de cursus voorstelt · extra: true = extra info, niet uit de cursus (turquoise rand)
// tabel = kleine overzichtstabel (eerste rij = kolomkoppen)
// De structuur onderaan bepaalt het overzicht rechts (volgorde van de slides).

const kaarten_IT_deel2_les6 = [

  // ===== Inhoud (slide 2) =====
  { v: "Welke 2 onderwerpen komen aan bod in hoofdstuk 6?", a: "1. Optische geheugens\n2. Leesgeheugens", o: "Inhoud" },
  { v: "Zijn optische geheugens en leesgeheugens volatile of non-volatile?", a: "Non-volatile: de data blijft bewaard zonder stroom.", o: "Inhoud",
    uitleg: "Optische geheugens (cd, dvd, Blu-ray) en leesgeheugens (ROM, PROM, EPROM, EEPROM, flash) houden hun data bij, ook als de stroom uitvalt.\n\nDat is het verschil met het werkgeheugen (RAM) uit hoofdstuk 2: dat is volatile en verliest alles zonder stroom.\n\nOptisch betekent: de data wordt met licht gelezen, met een laser. Denk aan de cd, de dvd en de Blu-ray.\n\nLeesgeheugens zijn ROM en zijn opvolgers: PROM, EPROM, EEPROM en flash. Flash zit vandaag in usb-sticks, geheugenkaartjes en SSD's, dus ook die komen aan bod." },

  // ===== De cd: oorsprong (slide 3) =====
  { v: "Wie ontwikkelde de cd, en waarvoor?", a: "Philips en Sony, als geluidsdrager.", o: "De cd: oorsprong",
    uitleg: "Omdat een cd met licht gelezen wordt en niet met magnetisme, kan een magneet hem niet wissen. Dat is anders dan bij de harde schijf of de floppy uit hoofdstuk 5." },
  { v: "Waarvoor werd de cd later ook de standaard?", a: "Voor data-opslag.", o: "De cd: oorsprong" },
  { v: "Wat zijn de afmetingen van een cd?", n: 3, a: "12 cm diameter, 1,2 mm dik, met een gat van 15 mm.", o: "De cd: oorsprong" },
  { v: "Waarom is een cd ongevoelig voor magnetische velden?", a: "Hij is niet magnetisch: het is optische opslag.", o: "De cd: oorsprong", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s03_pits.jpg" },
  { v: "Waarom is een gewone cd een ROM?", a: "Read only memory: de data zit er bij het persen al in.", o: "De cd: oorsprong",
    uitleg: "Je kan een geperste cd alleen lezen, niet beschrijven." },
  { v: "Wat zie je op deze foto?", a: "Geperste pits in een cd, onder een elektronenmicroscoop.", o: "De cd: oorsprong", img: "afbeeldingen/ITdeel2les6_optisch/l6_s03_pits.jpg",
    uitleg: "De langwerpige putjes zijn de pits; de vlakke stukken ertussen zijn de lands. Samen vormen ze de 1'en en 0'en.\n\nEen cd wordt in de fabriek geperst. De data staat erop als heel kleine putjes (pits) met vlakke stukken ertussen (lands). Na het persen kan je niets meer veranderen: je kan de cd alleen lezen." },
  { v: "De cd in jaartallen", a: "De audio-cd kwam op de markt in 1982. De cd-rom voor computerdata volgde enkele jaren later.", o: "De cd: oorsprong", extra: true },
  { v: "In welk jaar kwam de cd op de markt, en waarvoor werd hij eerst gebruikt?", a: "In 1982, als audio-cd: een geluidsdrager voor muziek.", o: "De cd: oorsprong",
    uitleg: "De cd werd ontwikkeld door Philips en Sony. Geluidsdrager = iets waar je muziek op zet.\n\nLater werd de cd ook de standaard voor data-opslag op computers: de CD-ROM.\n\nGeluidsdrager betekent: iets waar je muziek op zet. De cd was dus eerst de audio-cd. Later ging men er ook computerdata op zetten." },

  // ===== Een cd lezen met licht (slide 4) =====
  { v: "Draait een cd altijd aan dezelfde snelheid?", a: "Nee: de draaisnelheid hangt af van de fabrikant en is niet altijd constant. Het buitenste gedeelte draait trager, het binnenste sneller.", o: "Een cd lezen met licht", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s04_spiraal.jpg" },
  { v: "Draait een cd aan de buitenkant sneller of trager dan aan de binnenkant?", a: "Trager.", o: "Een cd lezen met licht",
    uitleg: "Een rondje buiten is langer, dus er komt per toer meer data voorbij.\n\nDe data staat op één lang spoor in de vorm van een spiraal, van binnen naar buiten (rood op de tekening). Een rondje aan de buitenkant is veel langer dan een rondje aan de binnenkant. Daarom draait de schijf buiten trager: zo komt de data altijd ongeveer even snel voorbij de laser." },
  { v: "Hoe ziet het spoor van een cd eruit op deze tekening?", a: "Eén lang spiraalvormig spoor, van binnen naar buiten.", o: "Een cd lezen met licht", img: "afbeeldingen/ITdeel2les6_optisch/l6_s04_spiraal.jpg" },
  { v: "Waarmee wordt een cd gelezen?", a: "Met een laserstraal van 780 nm, die onzichtbaar is.", o: "Een cd lezen met licht", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s04_doorsnede.jpg" },
  { v: "Hoe codeert een cd een 1 en een 0?", a: "De putjes geven een andere reflectie van het laserlicht.", o: "Een cd lezen met licht" },
  { v: "Welke lagen van een cd staan op plaats 1 tot 4?", a: "1 = label\n2 = acryl (acrylic)\n3 = aluminium (aluminum)\n4 = polycarbonaat (polycarbonate plastic)", o: "Een cd lezen met licht", img: "afbeeldingen/ITdeel2les6_optisch/l6_s04_doorsnede_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s04_doorsnede.jpg",
    uitleg: "De laser komt van onderen door het polycarbonaat; het aluminium weerkaatst het licht." },
  { v: "780 nm en CLV", a: "780 nm (nanometer) is infrarood licht: net buiten wat je oog kan zien.\n\nDat de schijf buiten trager draait zodat de data aan een vaste snelheid voorbijkomt, heet CLV: constant linear velocity.", o: "Een cd lezen met licht", extra: true },
  { v: "Welke laag van een cd weerkaatst het licht, en langs welke kant leest de laser?", a: "De aluminiumlaag weerkaatst het licht. De laser leest langs onderen, door het doorzichtige polycarbonaat.", o: "Een cd lezen met licht",
    uitleg: "Een cd bestaat uit lagen (samen 1,2 mm dik): label, acryl, aluminium en polycarbonaat.\n\nDe laser schijnt van onderen door het polycarbonaat (doorzichtig plastic) op het aluminium. Het aluminium weerkaatst het licht terug naar een sensor. Op een pit komt het licht anders terug dan op een land: zo leest de speler 1 en 0.\n\nDe laser schijnt van onderen door het doorzichtige plastic (polycarbonaat) op een dun laagje aluminium. Dat aluminium weerkaatst het licht terug naar een sensor. Waar een putje zit, komt het licht anders terug dan op een vlak stuk. Die verschillen leest de speler als 1 en 0." },

  // ===== Krassen en error correction (slide 5) =====
  { v: "Hoeveel van de bits op een cd is error-correcting code (ECC)?", a: "Meer dan 10%.", o: "Krassen en error correction" },
  { v: "Waarvoor staat ECC?", a: "Error-correcting code.", o: "Krassen en error correction" },
  { v: "Hoe noem je het dat meer dan 10% van de bits op een cd extra controlebits zijn?", a: "Redundantie.", o: "Krassen en error correction" },
  { v: "Waarom speelt een cd met krassen en stof toch verder?", a: "De lezer herkent en herstelt de fouten met de extra bits (ECC).", o: "Krassen en error correction" },
  { v: "Gaat er data verloren bij een kleine kras op een cd?", a: "Nee.", o: "Krassen en error correction" },
  { v: "ECC en de verspreide data", a: "ECC werkt zoals parity bij RAID: extra informatie waarmee je ontbrekende stukjes kan terugrekenen.\n\nDe data staat bovendien verspreid op de schijf. Een kras veegt daardoor niet één lang stuk weg, maar telkens kleine stukjes die hersteld kunnen worden. Bij een grote kras lukt het herstel niet meer.", o: "Krassen en error correction", extra: true },
  { v: "Wat doet de lezer met de ECC-bits, en waarom wordt de data op een cd verspreid weggeschreven?", a: "Met de ECC-bits herkent en herstelt de lezer fouten.\nDe data wordt verspreid weggeschreven, zodat een kras telkens maar kleine stukjes van verschillende blokken wegveegt. Die kleine stukjes kan de ECC herstellen.", o: "Krassen en error correction",
    uitleg: "ECC = error-correcting code: meer dan 10% van de bits op een cd is extra controle-informatie (redundantie).\n\nStonden de bits van één blok allemaal naast elkaar, dan zou een kras een heel blok vernielen, en dat kan ECC niet meer herstellen. Door de bits te spreiden, raakt een kras van elk blok maar een paar bits.\n\nHet idee lijkt op parity bij RAID (hoofdstuk 5): extra informatie om ontbrekende data terug te rekenen.\n\nRedundantie betekent: er staat meer op de schijf dan strikt nodig. Een deel van de bits is geen data, maar controle-informatie (ECC). Leest de laser door een kras een paar bits verkeerd, dan kan de lezer met die extra bits uitrekenen wat er had moeten staan." },

  // ===== CD-R: eenmalig beschrijfbaar (slide 6) =====
  { v: "Hoe vaak kan je een CD-R beschrijven?", a: "1 keer ('recordable').", o: "CD-R: eenmalig beschrijfbaar" },
  { v: "Worden de pits en lands van een CD-R geperst?", a: "Nee, ze worden 'gebrand'.", o: "CD-R: eenmalig beschrijfbaar" },
  { v: "Waarvoor dient het spoor dat al op een lege CD-R staat?", a: "Om de laserstraal te leiden en de snelheid van de cd te bepalen.", o: "CD-R: eenmalig beschrijfbaar",
    uitleg: "Een lege CD-R heeft nog geen data, maar wel al een voorgevormd spoor. Daardoor weet de schrijflaser waar hij moet schrijven en hoe snel de schijf draait." },
  { v: "Welke laag gebruikt een CD-R in plaats van geperste putjes?", a: "Een laag kleurstof (dye).", o: "CD-R: eenmalig beschrijfbaar", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s06_cdr.jpg" },
  { v: "Wat doet de schrijflaser bij een CD-R?", a: "Hij verhit de kleurstof: die plek weerkaatst daarna minder.", o: "CD-R: eenmalig beschrijfbaar" },
  { v: "Kan je een gebrande plek op een CD-R terug wissen?", a: "Nee: wat gebrand is, blijft gebrand.", o: "CD-R: eenmalig beschrijfbaar" },
  { v: "Wat zie je op deze foto, en waar komt de kleur vandaan?", a: "De onderkant van een lege CD-R. De kleur komt van de kleurstof (dye).", o: "CD-R: eenmalig beschrijfbaar", img: "afbeeldingen/ITdeel2les6_optisch/l6_s06_cdr.jpg",
    uitleg: "De foto toont de onderkant van een lege CD-R: de kleur komt van de kleurstof." },
  { v: "Waarvoor staat de R in CD-R, en waarom zeggen we 'een cd branden'?", a: "R = recordable (beschrijfbaar).\n'Branden', omdat de laser de laag kleurstof verhit in plaats van putjes te persen.", o: "CD-R: eenmalig beschrijfbaar",
    uitleg: "Een CD-R kan je 1 keer beschrijven. De schrijflaser verhit de kleurstof (dye): die plek weerkaatst daarna minder licht, zoals een pit. Wat gebrand is, blijft gebrand: je kan het niet meer wissen.\n\nDaarom heet het 'een cd branden'. Een gebrande plek weerkaatst slecht, net zoals een putje op een geperste cd. De speler ziet dus hetzelfde verschil tussen 1 en 0." },

  // ===== CD-RW: herschrijfbaar (slide 7) =====
  { v: "Wanneer werd de cd uitgebreid voor read/write (herschrijfbaar)?", a: "Midden jaren 90.", o: "CD-RW: herschrijfbaar" },
  { v: "Volgens welk principe werkt een CD-RW?", a: "Phase change (fasewisseling).", o: "CD-RW: herschrijfbaar",
    uitleg: "Fasewisseling = de opnamelaag van de CD-RW wisselt tussen twee toestanden (fasen):\n- Amorf: de atomen liggen wanordelijk. De laag weerkaatst slecht: de lezer leest die plek als een pit.\n- Kristallijn: de atomen liggen netjes geordend. De laag weerkaatst goed: de lezer leest die plek als een land.\n\nDe laser verhit de laag tot een van twee temperaturen:\n- Heel heet: de laag smelt en koelt meteen weer af. De atomen hebben geen tijd om zich te ordenen, dus de laag wordt amorf. Zo schrijf je.\n- Minder heet: de atomen krijgen tijd om zich netjes te ordenen, dus de laag kristalliseert weer. Zo wis je.\n\nOmdat je dat telkens opnieuw kan doen, kan je een CD-RW wissen en opnieuw beschrijven. RW = rewritable (herschrijfbaar).\n\nBij een CD-ROM zijn de pits echte putjes in het plastic. Een CD-R heeft een kleurstoflaag die blijvend verandert. De CD-RW is de enige van de drie die je kan wissen." },
  { v: "Wat gebeurt er als de laser de laag van een CD-RW heel heet maakt?", a: "De laag wordt amorf en weerkaatst slecht, zoals een pit.", o: "CD-RW: herschrijfbaar",
    uitleg: "Amorf = de atomen liggen wanordelijk, zonder vaste structuur.\n\nWat er gebeurt:\n- De laser maakt de laag heel heet: ze smelt even.\n- Daarna koelt ze meteen af, zo snel dat de atomen geen tijd hebben om zich netjes te ordenen. Ze blijven wanordelijk liggen: de laag is amorf.\n\nEen amorfe plek weerkaatst het laserlicht slecht. De lezer ziet weinig licht terugkomen, net zoals bij een pit op een gewone cd. Zo schrijf je gegevens op een CD-RW.\n\nHet omgekeerde: maakt de laser de laag minder heet, dan krijgen de atomen tijd om zich te ordenen. De laag wordt weer kristallijn en weerkaatst goed, zoals een land. Zo wis je." },
  { v: "Wat gebeurt er als de laser de laag van een CD-RW minder heet maakt?", a: "De laag kristalliseert en weerkaatst weer goed, zoals een land.", o: "CD-RW: herschrijfbaar",
    uitleg: "Kristallijn = de atomen liggen netjes geordend, in een vast patroon.\n\nWat er gebeurt:\n- De laser verwarmt de laag, maar niet tot ze smelt.\n- De atomen kunnen dan bewegen en hebben genoeg tijd om zich netjes te ordenen. De laag kristalliseert.\n\nEen kristallijne plek weerkaatst het laserlicht goed. De lezer ziet veel licht terugkomen, net zoals bij een land op een gewone cd. Zo wis je een plek op een CD-RW: een amorfe plek (pit) wordt weer kristallijn (land)." },
  { v: "Tot hoeveel temperaturen verhit de laser de laag van een CD-RW?", a: "Tot een van twee temperaturen: heel heet of minder heet.", o: "CD-RW: herschrijfbaar" },
  { v: "Waarom kunnen oudere lezers soms geen CD-RW lezen?", a: "Het verschil tussen 0 en 1 is minder duidelijk 'zichtbaar'. Een voorbeeld is een oude audio-cd-speler.", o: "CD-RW: herschrijfbaar" },
  { v: "Wat betekenen phase change, amorf en kristallijn bij een CD-RW?", a: "Phase change (fasewisseling): de laag wisselt tussen amorf en kristallijn.\nAmorf: de atomen liggen wanordelijk: mat, weinig reflectie.\nKristallijn: de atomen liggen netjes geordend: glanzend, goede reflectie.", o: "CD-RW: herschrijfbaar",
    uitleg: "Fase = de toestand van het materiaal.\n\n- De laser verhit de laag heel heet: ze wordt amorf en weerkaatst slecht. Die plek leest als een pit.\n- De laser verhit de laag minder heet: ze kristalliseert en weerkaatst weer goed. Die plek leest als een land: zo wis je.\n\nOmdat je telkens kan wisselen, kan je een CD-RW wissen en opnieuw beschrijven. RW = rewritable (herschrijfbaar).\n\nFase betekent hier: de toestand van het materiaal. Amorf = de deeltjes liggen door elkaar, zoals glas: dat weerkaatst slecht. Kristallijn = de deeltjes liggen netjes geordend: dat weerkaatst goed. Omdat je met de laser telkens van de ene naar de andere toestand kan gaan, kan je de schijf wissen en opnieuw beschrijven.\n\nEen amorfe plek weerkaatst wel minder dan een kristallijne, maar het verschil is kleiner dan tussen een echt putje en een vlak stuk. Een oude speler met een minder gevoelige sensor ziet dat verschil niet goed." },

  // ===== ROM, R en RW vergeleken (slide 8) =====
  { v: "Vergelijk CD-ROM, CD-R en CD-RW: hoe komt de data erop, hoe vaak kan je schrijven, en leest elke speler het?", a: "", o: "ROM, R en RW vergeleken",
    tabel: [["", "Read-only", "Recordable", "Rewritable"], ["Voorbeeld", "CD-ROM", "CD-R", "CD-RW"], ["Hoe de data erop komt", "pits en lands geperst in de fabriek", "de laser verbrandt een laag kleurstof (dye)", "de laser maakt de laag amorf of kristallijn (phase change)"], ["Hoe vaak schrijven", "nooit", "1 keer", "vaak: wissen en opnieuw schrijven"], ["Leest elke speler het?", "ja", "meestal", "oudere spelers niet"]],
    uitleg: "Voor de lezer is het hetzelfde: een plek die slecht weerkaatst, leest als een pit.\n- CD-ROM: de pits en lands worden in de fabriek in het plastic geperst.\n- CD-R: de laser verhit een laag kleurstof (dye); die plek weerkaatst daarna minder, zoals een pit.\n- CD-RW: de laser maakt de laag amorf (weerkaatst slecht) of kristallijn (weerkaatst goed): phase change.\n\nKort: geperst, gebrand, fasewisseling." },
  { v: "Waarom maakt het voor de lezer niet uit of een cd geperst, gebrand of herschreven is?", a: "Voor de lezer is het hetzelfde: een plek die slecht weerkaatst, leest als een pit.", o: "ROM, R en RW vergeleken" },
  { v: "Geef het voorbeeld van read-only, recordable en rewritable bij de cd.", a: "Read-only: CD-ROM\nRecordable: CD-R\nRewritable: CD-RW", o: "ROM, R en RW vergeleken" },
  { v: "Hoe komt de data op een CD-ROM, een CD-R en een CD-RW?", a: "CD-ROM: pits en lands geperst in de fabriek.\nCD-R: de laser verbrandt een laag kleurstof (dye).\nCD-RW: de laser maakt de laag amorf of kristallijn (phase change).", o: "ROM, R en RW vergeleken" },
  { v: "Hoe vaak kan je schrijven op een CD-ROM, een CD-R en een CD-RW?", a: "CD-ROM: nooit.\nCD-R: 1 keer.\nCD-RW: vaak: wissen en opnieuw schrijven.", o: "ROM, R en RW vergeleken" },
  { v: "Leest elke speler een CD-ROM, een CD-R en een CD-RW?", a: "CD-ROM: ja.\nCD-R: meestal.\nCD-RW: oudere spelers niet.", o: "ROM, R en RW vergeleken" },

  // ===== De dvd (slide 9) =====
  { v: "Waarvoor staat dvd?", a: "Digital Versatile Disc.", o: "De dvd" },
  { v: "Is een dvd groter of kleiner dan een CD-ROM?", a: "Even groot: zelfde afmeting als een CD-ROM.", o: "De dvd" },
  { v: "Wat is de capaciteit van een dvd (1 laag), en waarom past er meer op dan op een cd?", a: "4,7 GB: de data ligt dichter bij elkaar.", o: "De dvd" },
  { v: "Welke laser gebruikt een dvd, en hoe verschilt die van de cd?", a: "Een rode laser, fijner gefocust dan bij de cd.", o: "De dvd" },
  { v: "Zijn de pits en lands van een dvd groter of kleiner dan bij een cd?", a: "Kleiner.", o: "De dvd" },
  { v: "Wat is een dual layer dvd?", a: "Een dvd met 2 lagen, gescheiden door een half doorlatende laag.", o: "De dvd" },
  { v: "Kan een dvd tweezijdig zijn?", a: "Ja, eventueel tweezijdig.", o: "De dvd" },
  { v: "Wat is er bij de dvd nog anders dan bij de cd, behalve de laser en de pits?", a: "Andere mechanismen voor adressering en error correction.", o: "De dvd" },
  { v: "Wat betekent 'versatile' in Digital Versatile Disc?", a: "Veelzijdig.", o: "De dvd",
    uitleg: "De dvd is veelzijdig: hij dient voor films, maar ook voor computerdata. Hij ziet eruit als een cd (zelfde afmeting), maar er past veel meer op: 4,7 GB, ongeveer 7 keer een cd van 700 MB.\n\nVersatile betekent veelzijdig: de dvd is voor films, maar ook voor data. Hij ziet er uit zoals een cd, maar er past veel meer op, omdat de putjes en de sporen dichter bij elkaar liggen." },
  { v: "Hoe kan de laser bij een dual-layer-dvd de onderste laag lezen, en wat betekent tweezijdig?", a: "De bovenste laag is half doorlatend: ze laat een deel van het licht door, zodat de laser scherp kan stellen op de laag eronder.\nTweezijdig: er staat aan beide kanten van de schijf data.", o: "De dvd",
    uitleg: "Dual layer = 2 datalagen boven elkaar: samen 8,5 GB in plaats van 4,7 GB.\n\nDe laser stelt scherp op een andere diepte om de ene of de andere laag te lezen.\n\nBij een tweezijdige dvd moet je de schijf omdraaien (of de speler leest beide kanten).\n\nDual layer: er liggen twee datalagen boven elkaar. De bovenste laag laat een deel van het licht door, zodat de laser door de eerste laag heen de tweede kan lezen; hij stelt gewoon scherp op een andere diepte.\n\nTweezijdig: er staat ook data op de andere kant van de schijf." },

  // ===== DVD: regiocodes (slide 10) =====
  { v: "Waarvoor werden dvd's vooral gebruikt?", a: "Voor films.", o: "DVD: regiocodes" },
  { v: "Waarom kreeg een dvd een regiocode?", a: "Films kwamen niet overal tegelijk uit.", o: "DVD: regiocodes",
    uitleg: "Filmmaatschappijen brachten een film bijvoorbeeld eerst in de VS uit en pas maanden later in Europa. Met een regiocode konden ze voorkomen dat iemand in Europa al een Amerikaanse dvd afspeelde.", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s10_regios.jpg" },
  { v: "Waar zit de regiocode van een dvd?", a: "Op de schijf, en ook in het toestel: in de hardware of in de software.", o: "DVD: regiocodes" },
  { v: "Op welke speler speelt een dvd met een regiocode af?", a: "Alleen op een speler uit dezelfde regio.", o: "DVD: regiocodes" },
  { v: "Hoeveel dvd-regio's toont deze kaart, en in welke regio valt België?", a: "De regio's 1 tot 6. België valt in regio 2.", o: "DVD: regiocodes", img: "afbeeldingen/ITdeel2les6_optisch/l6_s10_regios.jpg" },

  // ===== Blu-ray: capaciteit (slide 11) =====
  { v: "Waarom kwam er na de dvd de Blu-ray?", a: "Met HD-tv kwam meer data per film: ongeveer 5x meer bandbreedte dan een dvd.", o: "Blu-ray: capaciteit", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s11_capaciteit.jpg" },
  { v: "Hoeveel meer bandbreedte vraagt een HD-film ongeveer dan een dvd?", a: "Ongeveer 5x meer.", o: "Blu-ray: capaciteit" },
  { v: "Welke capaciteit hoort bij de staven 1 tot 5?", a: "1 = cd: 0,7 GB\n2 = dvd, 1 laag: 4,7 GB\n3 = dvd, 2 lagen: 8,5 GB\n4 = Blu-ray, 1 laag: 25 GB\n5 = Blu-ray, 2 lagen: 50 GB", o: "Blu-ray: capaciteit", img: "afbeeldingen/ITdeel2les6_optisch/l6_s11_capaciteit_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s11_capaciteit.jpg" },
  { v: "Hoeveel pixels heeft HD-beeld, en waarom was er daardoor de Blu-ray nodig?", a: "1920 × 1080 pixels. Een film in HD is zoveel meer data (ongeveer 5 keer meer bandbreedte) dat een dvd te klein was.", o: "Blu-ray: capaciteit",
    uitleg: "Pixel = één puntje van het beeld. 1920 × 1080 = ongeveer 2 miljoen pixels per beeld, en een film heeft 24 of meer beelden per seconde.\n\nCapaciteit: dvd 4,7 GB (1 laag), Blu-ray 25 GB (1 laag): ongeveer 5 keer meer.\n\nHD-beelden hebben veel meer pixels, dus een film in HD is veel meer data. Een dvd was daarvoor te klein, en zo kwam de Blu-ray.\n\nDe grafiek toont de capaciteit per schijf: cd 0,7 GB · dvd 1 laag 4,7 GB · dvd 2 lagen 8,5 GB · Blu-ray 1 laag 25 GB · Blu-ray 2 lagen 50 GB." },

  // ===== Kortere golflengte, meer data (slide 12) =====
  { v: "Welke laser en golflengte gebruikt een cd?", a: "Een infrarode laser van 780 nm.", o: "Kortere golflengte, meer data" },
  { v: "Welke laser en golflengte gebruikt een dvd?", a: "Een rode laser van 650 nm.", o: "Kortere golflengte, meer data" },
  { v: "Welke laser en golflengte gebruikt een Blu-ray?", a: "Een blauwe laser van 405 nm.", o: "Kortere golflengte, meer data" },
  { v: "Wat is de track pitch van een cd, een dvd en een Blu-ray?", a: "Cd: 1,6 micron.\nDvd: 0,74 micron.\nBlu-ray: 0,32 micron.", o: "Kortere golflengte, meer data" },
  { v: "Waarom past er meer data op een schijf met een kortere golflengte?", a: "Een kleinere lichtvlek: de sporen en putjes kunnen dichter op elkaar.", o: "Kortere golflengte, meer data", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s12_lasers.jpg" },
  { v: "Welke laser hoort bij 1, 2 en 3, en welke track pitch bij 4, 5 en 6?", a: "1 = cd: 780 nm (infrarood)\n2 = dvd: 650 nm (rood)\n3 = Blu-ray: 405 nm (blauw)\n4 = cd: 1,6 micron\n5 = dvd: 0,74 micron\n6 = Blu-ray: 0,32 micron", o: "Kortere golflengte, meer data", img: "afbeeldingen/ITdeel2les6_optisch/l6_s12_lasers_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s12_lasers.jpg",
    uitleg: "Op de tekening staat bij de cd 'red laser', maar volgens de cursus is de cd-laser infrarood (780 nm)." },
  { v: "Wat is track pitch precies?", a: "Track pitch is de afstand van het midden van een spoor tot het midden van het spoor ernaast. Hoe kleiner die afstand, hoe meer sporen er op de schijf passen. Vergelijk het met de track density (TPI) uit hoofdstuk 5.", o: "Kortere golflengte, meer data", extra: true },
  { v: "Wat is track pitch, en hoeveel mm is 1 micron?", a: "Track pitch: de afstand tussen twee sporen die naast elkaar liggen.\n1 micron = 0,001 mm (een duizendste millimeter).", o: "Kortere golflengte, meer data",
    uitleg: "Track pitch: cd 1,6 micron, dvd 0,74 micron, Blu-ray 0,32 micron.\n\nHoe korter de golflengte van de laser, hoe kleiner de lichtvlek. Met een kleinere lichtvlek kan je de sporen dichter bij elkaar leggen: kleinere track pitch, dus meer data op dezelfde schijf.\n\nDe naam Blu-ray komt van de blauwe laser (blue ray) van 405 nm." },

  // ===== Blu-ray: opkomst en vandaag (slide 13) =====
  { v: "Waarom waren Blu-ray-spelers eerst duur?", a: "De blauwe laser was nieuw en schaars.", o: "Blu-ray: opkomst en vandaag" },
  { v: "Hoe komen films en software vandaag vooral bij ons?", a: "Via streaming en downloads.", o: "Blu-ray: opkomst en vandaag",
    uitleg: "Daarom hebben laptops bijna nooit nog een optische lezer." },
  { v: "Tegen welk formaat won Blu-ray de strijd, en wanneer?", a: "Tegen HD DVD, in 2008.", o: "Blu-ray: opkomst en vandaag",
    uitleg: "Na de dvd waren er 2 concurrerende formaten voor HD-films: Blu-ray (o.a. Sony) en HD DVD (o.a. Toshiba). In 2008 stopte HD DVD, en Blu-ray werd de standaard.\n\nDe cursus zet bij deze slide 'Ter informatie'." },

  // ===== De standaarden op een rij (slide 14) =====
  { v: "Geef van cd, dvd en Blu-ray de laser, de capaciteit en de read-only, recordable en rewritable versies.", a: "", o: "De standaarden op een rij",
    tabel: [["", "CD", "DVD", "Blu-ray"], ["Laser", "infrarood, 780 nm", "rood, 650 nm", "blauw, 405 nm"], ["Capaciteit, 1 laag", "700 MB", "4,7 GB", "25 GB"], ["Capaciteit, 2 lagen", "", "8,5 GB", "50 GB"], ["Read-only (geperst)", "CD-ROM", "DVD-ROM", "BD-ROM"], ["Recordable (1x)", "CD-R", "DVD-R, DVD+R", "BD-R"], ["Rewritable", "CD-RW", "DVD-RW, DVD+RW", "BD-RE"], ["Speler leest ook", "", "cd", "dvd en cd"]],
    uitleg: "- Niet elke lezer leest alles: een cd-speler leest geen dvd, een dvd-speler geen Blu-ray. Een nieuwere speler leest wel de oudere formaten (achterwaarts compatibel).\n- Oudere toestellen lezen soms geen RW, of maar een van -R en +R.\n- BD = Blu-ray Disc. Een cd met 2 lagen bestaat niet.\n- Hoe korter de golflengte van de laser, hoe groter de capaciteit." },
  { v: "Kan een cd-speler een dvd lezen? En een dvd-speler een Blu-ray?", a: "Nee, niet elke lezer leest alles: een cd-speler leest geen dvd, een dvd-speler geen Blu-ray.", o: "De standaarden op een rij" },
  { v: "Wat leest een dvd-speler ook nog? En een Blu-ray-speler?", a: "Een dvd-speler leest ook cd's.\nEen Blu-ray-speler leest ook dvd's en cd's.", o: "De standaarden op een rij" },
  { v: "Welke problemen kunnen oudere toestellen hebben met beschrijfbare schijven?", n: 2, a: "Ze lezen soms geen RW, of maar een van -R en +R.", o: "De standaarden op een rij" },
  { v: "Wat is de capaciteit van een cd, een dvd en een Blu-ray met 1 laag?", a: "Cd: 700 MB.\nDvd: 4,7 GB.\nBlu-ray: 25 GB.", o: "De standaarden op een rij" },
  { v: "Wat is de capaciteit van een dvd en een Blu-ray met 2 lagen?", a: "Dvd: 8,5 GB.\nBlu-ray: 50 GB.", o: "De standaarden op een rij" },
  { v: "Hoe heten de read-only (geperste) versies van cd, dvd en Blu-ray?", n: 3, a: "CD-ROM, DVD-ROM en BD-ROM.", o: "De standaarden op een rij" },
  { v: "Hoe heten de recordable versies (1x schrijven) van cd, dvd en Blu-ray?", n: 4, a: "CD-R, DVD-R en DVD+R, BD-R.", o: "De standaarden op een rij" },
  { v: "Hoe heten de rewritable versies van cd, dvd en Blu-ray?", n: 4, a: "CD-RW, DVD-RW en DVD+RW, BD-RE.", o: "De standaarden op een rij" },
  { v: "Welke rewritable Blu-ray-variant heet niet 'RW'?", a: "BD-RE.", o: "De standaarden op een rij" },
  { v: "DVD-R en DVD+R", a: "DVD-R en DVD+R zijn twee concurrerende formaten van verschillende fabrikantengroepen. Ze doen hetzelfde (1 keer beschrijven), maar werken net iets anders. Daarom kunnen sommige oudere spelers maar een van de twee lezen. Moderne toestellen lezen allebei.\n\nBD-RE staat voor Blu-ray Disc Recordable Erasable.", o: "De standaarden op een rij", extra: true },
  { v: "Wat zijn DVD-R en DVD+R?", a: "Twee concurrerende formaten van eenmalig beschrijfbare dvd's, van verschillende groepen fabrikanten.", o: "De standaarden op een rij",
    uitleg: "Beide zijn recordable: je kan ze 1 keer beschrijven. Er zijn ook de herschrijfbare versies DVD-RW en DVD+RW.\n\nOudere toestellen kunnen soms maar een van beide (-R of +R) lezen. Nieuwere spelers lezen meestal beide." },

  // ===== ROM: read only memory (slide 15) =====
  { v: "Waarvoor staat ROM?", a: "Read Only Memory.", o: "ROM: read only memory",
    uitleg: "ROM = Read Only Memory = geheugen dat je alleen kan lezen.\n\n- Read = lezen, only = alleen, memory = geheugen.\n- De inhoud wordt in de fabriek in de chip gezet en kan daarna niet meer veranderen.\n- ROM is non-volatile (bestendig): de inhoud blijft bewaard zonder stroom.\n\nROM is de basis van een hele familie leesgeheugens. Elke volgende soort voegt iets toe:\n- PROM: je kan er zelf 1 keer op schrijven.\n- EPROM: je kan wissen met uv-licht.\n- EEPROM: je kan elektrisch wissen.\n- Flash: je kan elektrisch wissen, per blok en snel." },
  { v: "Wanneer krijgt een ROM zijn inhoud?", a: "Bij de productie wordt de inhoud vastgebrand: daarna enkel lezen, niet schrijven.", o: "ROM: read only memory",
    uitleg: "Bij een ROM bepaalt de fabriek de inhoud tijdens de productie. De bits worden als het ware in de chip gebakken: welke bit 0 en welke 1 is, ligt vast in de structuur van de chip zelf.\n\n- Na de productie kan je alleen nog lezen.\n- Schrijven, wissen of aanpassen kan nooit meer.\n\nDaarom loont een ROM alleen bij grote aantallen dezelfde toestellen, waarvan de inhoud zeker niet meer moet veranderen." },
  { v: "Waarom noemt men ROM 'dode geheugens'?", a: "De inhoud ligt vast en kan niet meer veranderen, zoals bij een gloeilamp (cfr. gloeilamp).", o: "ROM: read only memory",
    uitleg: "Een ROM is \"dood\": de inhoud ligt vast vanaf de fabriek. Je kan er niets meer bij schrijven, niets wissen en niets aanpassen.\n\nDat is ook een voordeel: de inhoud kan niet per ongeluk overschreven worden, ook niet door een virus, en hij blijft bewaard zonder stroom.\n\nHet nadeel: zit er een fout in de inhoud, dan kan je die niet verbeteren. Je moet dan een nieuwe chip maken en de oude vervangen. Daarom kwamen later geheugens die je wel kan wissen (EPROM, EEPROM, flash)." },
  { v: "Wat betekent non-volatile (bestendig)?", a: "De informatie gaat niet verloren als de stroom uitvalt.", o: "ROM: read only memory",
    uitleg: "Non-volatile is het tegenovergestelde van het werkgeheugen (RAM) uit hoofdstuk 2, dat alles kwijt is als de stroom uitvalt.\n\nVolatile = vluchtig, non-volatile = bestendig.\n\n- Non-volatile: de gegevens blijven bewaard zonder stroom. Alle leesgeheugens (ROM, PROM, EPROM, EEPROM, flash) en ook harde schijven, SSD's en optische schijven.\n- Volatile: alles is weg als de stroom uitvalt. Het werkgeheugen (SRAM, DRAM, SDRAM).\n\nDaarom moet de BIOS in een bestendig geheugen zitten: hij moet er al zijn op het moment dat je de pc aanzet." },
  { v: "Waarvoor werd ROM vroeger bijvoorbeeld gebruikt?", a: "Voor de BIOS van computers.", o: "ROM: read only memory",
    uitleg: "BIOS = Basic Input/Output System: het eerste programma dat draait als je de pc aanzet.\n\n- Het test de hardware (processor, werkgeheugen, toetsenbord ...).\n- Het zoekt een opstartschijf en start het besturingssysteem op.\n\nDat programma moet er al zijn voor er iets anders geladen is, ook als de pc net aangezet wordt. Daarom moest het in een bestendig geheugen (non-volatile) zitten: vroeger een ROM op het moederbord.\n\nHet nadeel van ROM: een update van de BIOS was onmogelijk zonder de chip te vervangen. Vandaag zit de BIOS (of opvolger UEFI) in flashgeheugen, zodat je hem kan updaten." },
  { v: "Waarvoor staat PROM?", a: "Programmable ROM.", o: "ROM: read only memory",
    uitleg: "PROM = Programmable ROM = programmeerbaar ROM.\n\n- Bij een gewone ROM bepaalt de fabriek de inhoud.\n- Bij een PROM bepaal jij de inhoud: je koopt een lege chip en schrijft er zelf 1 keer je gegevens op.\n\nDaarna gedraagt de PROM zich als een gewone ROM: alleen lezen, en de inhoud blijft bewaard zonder stroom. Een andere naam is OTP: one-time programmable (één keer programmeerbaar)." },
  { v: "Hoe wordt een PROM geleverd, en hoe vaak kan je erop schrijven?", a: "Leeg. De gebruiker kan 1x schrijven, en vanaf dan blijft alles bewaard.", o: "ROM: read only memory",
    uitleg: "Een PROM komt leeg uit de fabriek: alle bits hebben dezelfde beginwaarde.\n\n- De gebruiker schrijft er 1 keer zijn gegevens op met een PROM programmer.\n- Daarna kan je niets meer wissen of veranderen: de PROM is vanaf dan een gewone ROM.\n- De gegevens blijven bewaard zonder stroom (non-volatile).\n\nSchrijf je een fout weg, dan is de chip niet meer bruikbaar en neem je een nieuwe lege PROM." },
  { v: "Waarvoor wordt PROM vooral gebruikt?", a: "Voor prototypes en kleine reeksen.", o: "ROM: read only memory",
    uitleg: "Een ROM laten maken kost veel geld voor de eerste chip: de fabriek moet een speciale productie opzetten met jouw inhoud erin. Pas bij duizenden stuks wordt elke chip goedkoop.\n\nEen PROM is een standaard lege chip die je zelf programmeert. Daarom past hij bij:\n- prototypes: een eerste testversie van een toestel, waar de software nog kan veranderen;\n- kleine reeksen: een paar honderd toestellen, waarvoor een eigen ROM te duur is.\n\nMoet de inhoud bij een prototype toch veranderen, dan neem je een nieuwe PROM. Later kwamen EPROM en EEPROM, die je kan wissen en opnieuw gebruiken." },
  { v: "Wat is het BIOS, en waar zit het vandaag?", a: "Het basisprogramma dat de pc opstart. Vroeger zat het in ROM, vandaag in flashgeheugen (als UEFI).", o: "ROM: read only memory",
    uitleg: "BIOS = Basic Input/Output System. Het start als eerste als je de pc aanzet: het test de hardware en start dan het besturingssysteem.\n\nVroeger zat het BIOS in een ROM-chip: niet aan te passen. Vandaag zit het (als UEFI, de opvolger van het BIOS) in flashgeheugen, zodat je het kan bijwerken (een BIOS-update)." },
  { v: "Waarom gebruikt men PROM voor kleine reeksen, en niet ROM?", a: "Een ROM laten maken is pas goedkoop bij grote aantallen.", o: "ROM: read only memory",
    uitleg: "De inhoud van een ROM wordt bij de productie in de chip vastgelegd. Daarvoor moet de fabriek eerst een speciaal masker maken: dat is duur, en loont pas bij heel veel chips.\n\nEen PROM wordt leeg geleverd: je schrijft hem zelf 1 keer. Voor een prototype of een kleine reeks is dat veel goedkoper.\n\nEen gewone ROM laten maken is pas goedkoop als je er heel veel nodig hebt (grote reeksen). Voor een prototype of een kleine reeks koop je liever lege PROM-chips en schrijf je ze zelf één keer." },
  { v: "Wat is ROM, en is het vluchtig of niet-vluchtig?", a: "ROM (read-only memory) is geheugen waarvan je de inhoud alleen kan lezen, niet wijzigen. De inhoud ligt vast bij de productie.\nROM is niet-vluchtig: de gegevens blijven bewaard zonder stroom, in tegenstelling tot RAM.", o: "ROM: read only memory", extra: true,
    uitleg: "Gebruik: voor software en gegevens die nooit hoeven te veranderen, zoals de opstartcode (firmware) van oudere computers, spelconsoles en rekenmachines, of vaste tabellen zoals lettertypes." },
  { v: "Wat is mask ROM?", a: "ROM waarvan de fabrikant de bits bij de productie vastlegt in de chip zelf, via een masker.\nElke cel is zo gemaakt dat ze een 0 of een 1 teruggeeft. Achteraf is dat niet meer aan te passen.", o: "ROM: read only memory", extra: true,
    uitleg: "Masker = een soort sjabloon waarmee de fabriek het patroon van de chip maakt. Bij mask ROM zit jouw inhoud in dat sjabloon: welke cel 0 en welke 1 is, ligt vast in de structuur van de chip.\n\nDaarom heet het ook mask ROM. Een nieuw masker maken kost veel geld, dus mask ROM loont alleen bij grote aantallen." },
  { v: "Wat is het voordeel van ROM, en wat zijn de 2 nadelen?", a: "Voordeel: goedkoop bij grote aantallen en betrouwbaar.\nNadelen:\n- een fout in de inhoud betekent dat je de chip moet vervangen;\n- een kleine oplage is duur, omdat je eerst een masker moet maken.", o: "ROM: read only memory", extra: true,
    uitleg: "Betrouwbaar: de inhoud kan niet per ongeluk veranderen of gewist worden, en blijft bewaard zonder stroom.\n\nDie nadelen zijn de reden voor de volgende stappen: met PROM kan je de chip 1 keer zelf programmeren, EPROM en EEPROM kan je wissen en opnieuw beschrijven, en flash is daarvan de snelle, goedkope opvolger." },
  { v: "Welke stappen volgden op ROM, en wat voegt elke stap toe?", a: "- PROM: je kan de chip 1 keer zelf programmeren.\n- EPROM en EEPROM: je kan ze wissen en opnieuw beschrijven.\n- Flash: de snelle, goedkope opvolger daarvan.", o: "ROM: read only memory", extra: true,
    uitleg: "De reden voor die stappen zijn de nadelen van ROM: een fout betekent een nieuwe chip, en een kleine oplage is duur omdat je eerst een masker moet maken." },
  { v: "Geef 4 voorbeelden waarin mask ROM gebruikt werd of wordt.", a: "- de opstartcode (BIOS) van oude computers\n- spelcartridges van oude consoles (NES, Game Boy)\n- vaste software in rekenmachines, wasmachines en speelgoed\n- lettertypes in printers", o: "ROM: read only memory", extra: true,
    uitleg: "Telkens gaat het om software of gegevens die nooit hoeven te veranderen, en om grote aantallen identieke toestellen. Dan is mask ROM goedkoop en betrouwbaar." },

  // ===== PROM: eenmalig programmeren (slide 16) =====
  { v: "Met welk toestel schrijf je gegevens naar een PROM?", a: "Met een PROM programmer.", o: "PROM: eenmalig programmeren",
    uitleg: "Een PROM programmer is een apart toestel waarin je de PROM-chip steekt, meestal aangesloten op een computer.\n\n- Op de computer kies je welke gegevens op de chip moeten.\n- De programmer zet die gegevens bit per bit op de chip.\n- Waar een bit moet veranderen, stuurt hij een spanningsstoot: een korte, hogere spanning die de zekering (fusable link) van die bit opblaast.\n\nPas daarna steek je de chip in het toestel waarvoor hij bedoeld is. Een PROM programmeer je dus niet in het toestel zelf." },
  { v: "Hoe worden de bits in een PROM geschreven?", a: "Met zekeringen ('fusable link') die men kan opblazen door een spanningsstoot.", o: "PROM: eenmalig programmeren",
    uitleg: "Elke bit in een PROM heeft een kleine zekering: een heel dun verbindingsdraadje in de chip (fusable link).\n\n- Zekering heel: er loopt stroom, dat leest als de ene waarde (bv. 1).\n- Zekering opgeblazen: er loopt geen stroom meer, dat leest als de andere waarde (bv. 0).\n\nEen lege PROM heeft alle zekeringen nog heel. Bij het programmeren blaast de PROM programmer met een spanningsstoot de zekeringen op van de bits die moeten veranderen." },
  { v: "Hoe traag is schrijven naar een PROM?", a: "Zeer traag: 1000x trager dan SRAM schrijven.", o: "PROM: eenmalig programmeren", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s16_prom.jpg",
    uitleg: "Bij een PROM moet de programmer voor elke bit die verandert een zekering opblazen met een spanningsstoot. Dat gaat bit per bit en kost telkens tijd.\n\nSRAM is het snelste geheugen: dat is de cache in de processor. Schrijven naar SRAM gaat in een paar nanoseconden.\n\n1000x trager dan SRAM is dus erg traag. Maar dat is niet erg: je programmeert een PROM maar 1 keer, en daarna lees je er alleen nog van." },
  { v: "Waarom kan je een PROM maar één keer programmeren?", a: "Een opgeblazen zekering (fusable link) kan je niet meer herstellen.", o: "PROM: eenmalig programmeren",
    uitleg: "Programmeren = zekeringen opblazen. Een zekering die doorgebrand is, kan je niet meer herstellen: het verbindingsdraadje is echt kapot.\n\nDaarom:\n- een bit die 1 keer veranderd is, blijft zo voor altijd;\n- je kan de chip niet wissen en opnieuw beschrijven;\n- schrijf je een fout weg, dan is de chip verloren.\n\nDat probleem loste de EPROM op: daar zit de bit niet in een zekering, maar in een elektrische lading die je met uv-licht kan wegnemen." },
  { v: "Welk soort chip zie je op deze foto, en hoe schrijf je er gegevens naar?", a: "Een PROM-chip. Je schrijft er gegevens naar met een PROM programmer.", o: "PROM: eenmalig programmeren", img: "afbeeldingen/ITdeel2les6_optisch/l6_s16_prom.jpg",
    uitleg: "Op de foto zie je een PROM-chip: een zwarte behuizing met twee rijen pootjes, zonder venster (een venster zou op een EPROM wijzen).\n\nGegevens schrijven:\n- Je steekt de chip in een PROM programmer, aangesloten op een computer.\n- De programmer blaast met spanningsstoten de zekeringen (fusable links) op van de bits die moeten veranderen.\n- Dat kan maar 1 keer: daarna is de PROM een gewone ROM." },
  { v: "Hoe stelt een PROM een bit voor, en hoeveel trager is schrijven naar een PROM dan naar SRAM?", a: "Met een zekering (fusable link): intact of doorgebrand, dus 1 of 0.\nSchrijven is 1000 keer trager dan naar SRAM.", o: "PROM: eenmalig programmeren",
    uitleg: "Met een PROM programmer blaas je met een spanningsstoot de zekeringen door die een 0 (of 1) moeten worden. Een doorgeblazen zekering maak je nooit meer heel: daarom kan je een PROM maar 1 keer programmeren.\n\nSRAM = het snelle geheugen dat als cache in de processor gebruikt wordt (hoofdstuk 2).\n\nElke bit is een piepklein zekeringetje. Heel blijft het een 1, en met een spanningsstoot blaas je het door, dan wordt het een 0 (of omgekeerd). Een doorgeblazen zekering maak je nooit meer heel: daarom kan je een PROM maar één keer programmeren." },
  { v: "Wat gebeurt er met de zekeringen als je een PROM programmeert?", a: "Elke cel bevat een klein zekeringetje (fuse). Met een programmeerapparaat en een hogere spanning brand je de zekeringen door waar een 0 moet komen. De andere cellen blijven 1.", o: "PROM: eenmalig programmeren", extra: true,
    uitleg: "Een lege PROM heeft alle zekeringen nog heel. Dat kan maar 1 keer: een doorgebrande zekering herstel je niet.\n\nVoordeel tegenover mask ROM: je hebt geen duur fabrieksmasker nodig." },
  { v: "Wat is het voordeel van PROM tegenover mask ROM, en waarom kan je hem maar 1 keer programmeren?", a: "Voordeel: je hebt geen dure fabrieksmaskers nodig.\nMaar 1 keer: een doorgebrande zekering herstel je niet.", o: "PROM: eenmalig programmeren", extra: true,
    uitleg: "De chip komt leeg uit de fabriek: elke cel bevat een klein zekeringetje (fuse). Met een programmeerapparaat en een hogere spanning brand je de zekeringen door waar een 0 moet komen." },
  { v: "Geef 3 toepassingen van PROM.", a: "- kleine oplagen of prototypes waarvoor een masker te duur is\n- vaste instellingen of codes in elektronica die nooit meer mogen veranderen\n- vandaag nog als OTP in microcontrollers, bv. voor beveiligingssleutels of serienummers", o: "PROM: eenmalig programmeren", extra: true,
    uitleg: "OTP = one-time programmable: 1 keer programmeerbaar. Dat is hetzelfde principe als PROM.\n\nEen microcontroller is een kleine computer op één chip, die een toestel aanstuurt (bv. een wasmachine of een afstandsbediening)." },

  // ===== EPROM: wissen met uv-licht (slide 17) =====
  { v: "Waarvoor staat EPROM?", a: "Erasable programmable ROM.", o: "EPROM: wissen met uv-licht",
    uitleg: "EPROM = Erasable Programmable ROM = uitwisbaar, programmeerbaar ROM.\n\n- Erasable: je kan de chip wissen, met uv-licht.\n- Programmable: je kan hem zelf beschrijven met een programmer.\n- ROM: de inhoud blijft bewaard zonder stroom.\n\nElke letter vooraan voegt iets toe aan de vorige: ROM, dan PROM (programmeerbaar), dan EPROM (ook uitwisbaar), dan EEPROM (elektrisch uitwisbaar)." },
  { v: "Welk voordeel heeft EPROM tegenover PROM?", a: "Je kan de door de gebruiker geschreven data toch nog aanpassen: de chip is uitwisbaar.", o: "EPROM: wissen met uv-licht",
    uitleg: "Bij een PROM ligt alles vast na 1 keer schrijven: een fout betekent een nieuwe chip.\n\nBij een EPROM kan je de door de gebruiker geschreven gegevens toch nog aanpassen:\n- wissen met uv-licht;\n- daarna opnieuw programmeren.\n\nDat was handig bij prototypes: de software van een nieuw toestel verandert vaak, en zo kan je dezelfde chip telkens opnieuw gebruiken.\n\nEen EPROM kan dus vaak opnieuw gebruikt worden, maar niet eindeloos, en de data blijft er ook niet voor altijd op staan.", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s17_eprom.jpg" },
  { v: "Hoe wis je een EPROM, en hoe lang duurt dat?", a: "Door blootstelling aan ultravioletstralen, gedurende 20 tot 40 minuten.", o: "EPROM: wissen met uv-licht",
    uitleg: "Een EPROM bewaart elke bit als een kleine elektrische lading die opgesloten zit in de chip. Ook zonder stroom blijft die lading zitten: daarom is EPROM bestendig.\n\nWissen:\n- Je haalt de chip uit het toestel en legt hem in een EPROM-wisser: een kastje met een uv-lamp.\n- Het ultraviolette licht geeft de opgesloten lading genoeg energie om te ontsnappen.\n- Na 20 tot 40 minuten is de hele chip leeg. Je kan niet een deel wissen: het is altijd alles.\n\nDaarna programmeer je hem opnieuw met een programmer." },
  { v: "Waarom heeft een EPROM een venster in de behuizing? Uit welk materiaal is het?", a: "Om het uv-licht tot bij de chip te laten. Het venster is uit kwartskristal.", o: "EPROM: wissen met uv-licht",
    uitleg: "Het uv-licht moet tot op de chip zelf kunnen komen. Daarom zit er bovenop de zwarte behuizing een klein rond of vierkant venster, met de chip eronder zichtbaar.\n\nHet venster is uit kwartskristal, omdat gewoon glas uv-licht tegenhoudt. Kwarts laat uv-licht door.\n\nEen EPROM herken je dus meteen aan dat venstertje." },
  { v: "Wat kan je met een EPROM na het uitwissen?", a: "Opnieuw programmeren: hij is herprogrammeerbaar.", o: "EPROM: wissen met uv-licht",
    uitleg: "Na het wissen is de EPROM weer leeg, net zoals een nieuwe chip. Je kan hem dan opnieuw programmeren met nieuwe gegevens.\n\nDat was het grote voordeel tegenover PROM: bij een prototype kan je de software verbeteren en dezelfde chip opnieuw gebruiken, in plaats van telkens een nieuwe chip te nemen.\n\nHerprogrammeerbaar = je kan hem opnieuw programmeren." },
  { v: "Wat zijn de 2 nadelen van een EPROM?", a: "Veel uitwissen verslechtert de eigenschappen.\nNa 10 jaar verliest hij toch informatie.", o: "EPROM: wissen met uv-licht",
    uitleg: "1. Veel uitwissen verslechtert de eigenschappen. Elke keer dat je wist en opnieuw schrijft, slijt de chip een beetje. Na veel keer (enkele honderden tot enkele duizenden keer) houdt hij de lading niet goed meer vast.\n\n2. Na 10 jaar verliest hij toch informatie. De opgesloten lading lekt heel traag weg. Na ongeveer 10 jaar kunnen bits omvallen.\n\nExtra nadeel uit de praktijk: wissen duurt lang (20 tot 40 minuten) en je moet de chip daarvoor uit het toestel halen. Dat loste de EEPROM op." },
  { v: "Welk soort chip zie je op deze foto, en waaraan herken je hem?", a: "Een EPROM: je herkent hem aan het venster (uit kwartskristal) in de behuizing.", o: "EPROM: wissen met uv-licht", img: "afbeeldingen/ITdeel2les6_optisch/l6_s17_eprom.jpg",
    uitleg: "Kenmerken van een EPROM op een foto:\n- een zwarte behuizing met twee rijen pootjes (DIP-behuizing);\n- bovenaan een klein rond of vierkant venster uit kwartskristal;\n- door het venster zie je de chip zelf zitten.\n\nVaak zit er een sticker over het venster, zodat zonlicht of tl-licht de chip niet per ongeluk langzaam wist." },
  { v: "Waarom heeft een EPROM een venster uit kwartskristal, en waarom plakt men er een sticker op?", a: "Kwarts laat uv-licht door, gewoon glas niet. Zo kan het uv-licht de chip wissen.\nDe sticker voorkomt dat zonlicht (dat ook uv bevat) de chip per ongeluk wist.", o: "EPROM: wissen met uv-licht",
    uitleg: "Een EPROM (Erasable Programmable ROM) wis je door hem 20 tot 40 minuten onder een uv-lamp te leggen.\n\nNadelen: veel wissen verslechtert de eigenschappen, en na ongeveer 10 jaar gaat de informatie toch verloren (de opgeslagen lading lekt weg).\n\nBij een PROM ben je vast na één keer schrijven. Een EPROM kan je wissen: je legt de chip 20 tot 40 minuten onder een uv-lamp. Het uv-licht moet tot bij de chip geraken, daarom zit er een doorzichtig venstertje van kwarts in de behuizing. Dat zie je op de foto." },
  { v: "Wat is een floating gate?", a: "Een geïsoleerd stukje geleider in een transistor, dat elektrische lading vasthoudt.\nLading of geen lading bepaalt of de cel een 0 of een 1 is.", o: "EPROM: wissen met uv-licht", extra: true,
    uitleg: "Floating = zwevend: het stukje geleider is rondom geïsoleerd, zodat de lading er niet uit kan. Daardoor blijft de lading jaren zitten, ook zonder stroom.\n\nEPROM, EEPROM en flash werken allemaal met floating gates. Het verschil zit in hoe je de lading er weer uit haalt: met uv-licht (EPROM) of elektrisch (EEPROM, flash)." },
  { v: "Hoe programmeer je een EPROM, hoe wis je hem, en welk deel wordt gewist?", a: "Programmeren: elektrisch, met een programmeerapparaat.\nWissen: onder sterk uv-licht, via het kwartsvenstertje bovenop. De chip moet daarvoor uit het apparaat.\nEr wordt altijd de hele chip in één keer gewist.", o: "EPROM: wissen met uv-licht", extra: true,
    uitleg: "Volgens de cursus duurt het wissen 20 tot 40 minuten.\n\nHet uv-licht geeft de lading in de floating gates genoeg energie om te ontsnappen. Je kan het licht niet op één cel richten, dus alles wordt samen gewist." },
  { v: "Geef 4 toepassingen van EPROM (vroeger en nu).", a: "- de BIOS van computers uit de jaren 80–90\n- ontwikkeling en testen van firmware (wissen en opnieuw proberen)\n- oude industriële apparatuur\n- vandaag grotendeels vervangen door flash", o: "EPROM: wissen met uv-licht", extra: true,
    uitleg: "Firmware = de vaste software in een toestel, die het toestel aanstuurt.\n\nFlash nam de plaats van EPROM in: je kan flash elektrisch wissen, in het toestel zelf, zonder uv-lamp." },

  // ===== EEPROM: elektrisch wissen (slide 18) =====
  { v: "Vergelijk flash EEPROM en full-featured EEPROM: wissen, kostprijs, ruimte op de chip en erase cycles.", a: "", o: "EEPROM: elektrisch wissen",
    tabel: [["", "Flash EEPROM", "Full-featured EEPROM"], ["Wissen", "per blok", "per byte"], ["Kostprijs", "goedkoop", "duurder"], ["Ruimte op de chip", "compact", "2,5x meer ruimte"], ["Erase cycles", "minder", "veel meer"]],
    uitleg: "Flash wist een heel blok tegelijk: dat is eenvoudiger te bouwen, dus compacter en goedkoper. Full-featured EEPROM kan één byte apart wissen; daarvoor is meer elektronica nodig (2,5 keer meer ruimte op de chip).\n\nErase cycles = hoe vaak je kan wissen voor het geheugen versleten is." },
  { v: "Waarvoor staat EEPROM?", a: "Electrically Erasable PROM.", o: "EEPROM: elektrisch wissen",
    uitleg: "EEPROM = Electrically Erasable Programmable ROM = elektrisch wisbaar, programmeerbaar ROM.\n\n- Electrically erasable: je wist hem met een elektrische spanning, niet met uv-licht.\n- Programmable: je kan hem zelf beschrijven.\n- ROM: hij blijft bestendig, de inhoud blijft bewaard zonder stroom.\n\nJe schrijft het soms als E²PROM (twee keer E)." },
  { v: "Hoe en waar wis je een EEPROM?", a: "Elektrisch, in het toestel zelf.", o: "EEPROM: elektrisch wissen",
    uitleg: "Het grote verschil met EPROM: je hoeft de chip niet uit het toestel te halen en onder een uv-lamp te leggen. Een elektrisch signaal wist hem, terwijl hij gewoon in het toestel zit." },
  { v: "Wat zijn de voordelen van EEPROM tegenover EPROM?", n: 2, a: "Geen uv-licht nodig en sneller wissen.", o: "EEPROM: elektrisch wissen",
    uitleg: "EPROM: de chip uit het toestel halen, 20 tot 40 minuten onder een uv-lamp leggen, en daarna opnieuw programmeren in een programmer.\n\nEEPROM: wissen en herschrijven gebeurt elektrisch, in het toestel zelf. De chip blijft gewoon zitten, en het wissen gaat veel sneller.\n\nDaardoor kan een toestel zijn eigen gegevens aanpassen, bijvoorbeeld een instelling die je verandert. Bij EPROM was dat onmogelijk." },
  { v: "Wat is het nadeel van EEPROM tegenover EPROM?", a: "Duurder.", o: "EEPROM: elektrisch wissen",
    uitleg: "Een EEPROM-chip is ingewikkelder: er moet extra schakeling op de chip om elektrisch te kunnen wissen. Daardoor is hij duurder dan een EPROM.\n\nBij de full-featured variant (wissen per byte) komt daar nog bij dat hij 2,5x meer ruimte op de chip nodig heeft dan flash. Meer ruimte per bit betekent minder bits per chip en een hogere prijs." },
  { v: "Hoe lang blijft de informatie in een EEPROM bewaard?", a: "Na 10 jaar is er informatieverlies.", o: "EEPROM: elektrisch wissen",
    uitleg: "Ook bij EEPROM zit elke bit als een elektrische lading opgesloten in de chip. Die lading lekt heel traag weg.\n\nNa ongeveer 10 jaar kan er informatie verloren gaan: sommige bits kunnen dan omvallen.\n\nDat geldt ook voor EPROM (zie slide 17). Voor gegevens die lang bewaard moeten worden, is het dus beter om ze af en toe opnieuw te schrijven of een back-up te maken." },
  { v: "Geef de 2 varianten van EEPROM.", a: "Flash EEPROM en full-featured EEPROM.", o: "EEPROM: elektrisch wissen",
    uitleg: "Er zijn twee varianten van EEPROM. Het verschil zit in hoe groot het stuk is dat je in één keer wist:\n- Flash EEPROM: wist per blok (veel bytes tegelijk). Goedkoop, compact, minder erase cycles. Dit werd het flashgeheugen uit usb-sticks en SSD's.\n- Full-featured EEPROM: wist per byte. Duurder, 2,5x meer ruimte op de chip, veel meer erase cycles. Handig voor kleine gegevens die vaak veranderen, zoals instellingen." },
  { v: "Hoe wissen flash EEPROM en full-featured EEPROM?", a: "Flash EEPROM: per blok.\nFull-featured EEPROM: per byte.", o: "EEPROM: elektrisch wissen",
    uitleg: "Flash EEPROM wist per blok: je kan niet één byte apart wissen. Wil je één byte veranderen, dan moet het hele blok gewist en opnieuw geschreven worden. Een blok bevat veel bytes (bijvoorbeeld honderden kilobytes).\n\nFull-featured EEPROM wist per byte: je kan één byte apart wissen en herschrijven, zonder de rest aan te raken.\n\nDaarom is full-featured EEPROM \"byte-alterable\" en flash niet (zie de tabel op slide 21)." },
  { v: "Welke EEPROM-variant is goedkoop, en welke duurder?", a: "Flash EEPROM: goedkoop.\nFull-featured EEPROM: duurder.", o: "EEPROM: elektrisch wissen",
    uitleg: "Flash EEPROM is goedkoop: omdat hij per blok wist, is de schakeling eenvoudiger en passen er veel meer bits op dezelfde oppervlakte. Meer bits per chip = lagere prijs per bit.\n\nFull-featured EEPROM is duurder: om elke byte apart te kunnen wissen, is er extra schakeling nodig. Die neemt plaats in (2,5x meer ruimte), dus minder bits per chip en een hogere prijs per bit." },
  { v: "Hoeveel meer ruimte op de chip neemt full-featured EEPROM in dan flash?", a: "2,5x meer ruimte; flash is compact.", o: "EEPROM: elektrisch wissen",
    uitleg: "Full-featured EEPROM neemt 2,5x meer ruimte in op de chip dan flash, voor dezelfde hoeveelheid gegevens.\n\nDe reden: om elke byte apart te kunnen wissen, heeft elke byte extra schakeling nodig. Flash deelt die schakeling over een heel blok, en is daardoor compact.\n\nDaarom zit flash in usb-sticks en SSD's met honderden gigabytes, en full-featured EEPROM alleen waar weinig gegevens bewaard moeten worden." },
  { v: "Welke EEPROM-variant heeft veel meer erase cycles?", a: "Full-featured EEPROM. Flash EEPROM heeft er minder.", o: "EEPROM: elektrisch wissen",
    uitleg: "Een erase cycle = één keer wissen en opnieuw beschrijven. Elke cel kan maar een beperkt aantal erase cycles aan: daarna slijt ze.\n\n- Full-featured EEPROM: veel meer erase cycles. Geschikt voor gegevens die heel vaak veranderen.\n- Flash EEPROM: minder erase cycles. Daarom gebruiken SSD's wear leveling: het schrijven wordt verdeeld over alle cellen, zodat ze gelijkmatig slijten." },
  { v: "Waar komt de naam 'flash' vandaan, en waarvoor gebruikt men full-featured EEPROM?", a: "Flash: een heel blok wordt in één flits gewist.\nFull-featured EEPROM: voor kleine hoeveelheden instellingen die vaak veranderen.", o: "EEPROM: elektrisch wissen",
    uitleg: "Flash EEPROM wist per blok: snel en goedkoop, maar je kan geen losse byte wissen.\n\nFull-featured EEPROM wist per byte en kan veel vaker gewist worden (meer erase cycles). Daarom gebruikt men het voor bv. instellingen van een toestel die regelmatig wijzigen." },
  { v: "Hoe werkt het wissen bij EEPROM, vergeleken met EPROM?", a: "Ook met floating gates, maar wissen gebeurt elektrisch: zonder uv-licht en terwijl de chip in het apparaat blijft.\nJe kan zelfs per byte wissen en herschrijven.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Bij EPROM moet de chip uit het apparaat en onder uv-licht, en wordt altijd de hele chip gewist." },
  { v: "Wat zijn de 3 nadelen van EEPROM, en waarvoor gebruikt men hem daarom?", a: "- trager\n- per bit duurder\n- beperkt aantal schrijfcycli (typisch 100.000 tot 1 miljoen)\nDaarom gebruikt men EEPROM voor kleine hoeveelheden instellingen.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Ook EEPROM werkt met floating gates, maar het wissen gebeurt elektrisch, zonder uv-licht en terwijl de chip in het apparaat blijft. Je kan zelfs per byte wissen en herschrijven.\n\nEen schrijfcyclus = één keer wissen en opnieuw schrijven." },
  { v: "Wat is full-featured EEPROM, en waarvoor is hij ideaal?", a: "De 'klassieke' EEPROM: je kan elke byte apart wissen en herschrijven, zonder de rest aan te raken.\nErg flexibel, ideaal voor kleine gegevens die af en toe veranderen: instellingen, kalibratiewaarden, serienummers.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Daarvoor heeft elke cel naast de geheugentransistor nog een extra selectietransistor nodig. Gevolg: grotere cellen, dus minder opslag per chip en duurder per bit." },
  { v: "Waarom heeft een full-featured EEPROM grotere cellen dan flash?", a: "Om elke byte apart te kunnen wissen, heeft elke cel naast de geheugentransistor nog een extra selectietransistor nodig.\nGevolg: grotere cellen, dus minder opslag per chip en duurder per bit.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Selectietransistor = een extra schakelaartje dat ervoor zorgt dat je precies die ene cel kan kiezen om te wissen, zonder de rest aan te raken.\n\nDaardoor is full-featured EEPROM erg flexibel: ideaal voor kleine gegevens die af en toe veranderen." },
  { v: "Wat moet er gebeuren als je in flash één byte wil aanpassen?", a: "Het hele blok moet gewist en opnieuw geschreven worden. Flash wist niet per byte, maar alleen per blok van vele kilobytes tegelijk.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Bij full-featured EEPROM kan je die ene byte apart wissen en herschrijven." },
  { v: "Waarom zijn flashcellen veel kleiner en goedkoper dan cellen van full-featured EEPROM?", a: "Flash wist alleen per blok van vele kilobytes tegelijk. Daardoor valt de extra selectietransistor per cel weg: de cellen zijn veel kleiner, dus veel meer opslag per chip en goedkoper.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Wil je bij flash één byte aanpassen, dan moet het hele blok gewist en opnieuw geschreven worden.\n\nKort samengevat: full-featured EEPROM wist per byte en is flexibel maar duur; flash wist per blok en is goedkoop en compact." },
  { v: "Vat full-featured EEPROM en flash kort samen.", a: "Full-featured EEPROM wist per byte en is flexibel maar duur.\nFlash wist per blok en is goedkoop en compact.", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Flash EEPROM (kortweg flash) is geschikt voor grote opslag: usb-sticks, geheugenkaarten, SSD's en firmware. Wissen van grote hoeveelheden tegelijk gaat snel." },
  { v: "Geef 4 toepassingen van full-featured EEPROM.", a: "- instellingen die bewaard moeten blijven zonder stroom, bv. de zenderlijst van een tv of de kalibratie van sensoren\n- serienummers en configuratie in moederborden, netwerkkaarten en geheugenmodules\n- chipkaarten en bankkaarten\n- autosleutels en de kilometerstand in auto's", o: "EEPROM: elektrisch wissen", extra: true,
    uitleg: "Telkens gaat het om weinig gegevens, die bewaard moeten blijven zonder stroom en die af en toe veranderen. Daarvoor is per byte wissen ideaal.\n\nKalibratie = de instelwaarden waarmee een sensor juiste metingen geeft." },

  // ===== Flash: de doorbraak (slide 19) =====
  { v: "Geef de 4 redenen voor de doorbraak van flash.", a: "1. Meer mogelijke herbeschrijvingen, hogere informatiedichtheid, lagere kost.\n2. Laag energieverbruik: ideaal voor draagbare toestellen.\n3. Zeer vlug tov. andere bestendige geheugens (vooral random lezen of schrijven).\n4. Betrouwbaar: geen mechanische onderdelen, compact tov. een HDD.", o: "Flash: de doorbraak",
    uitleg: "Flash is een EEPROM die per blok wist. Hij werd zeer populair om 4 redenen:\n\n1. Meer herbeschrijvingen, hogere informatiedichtheid, lagere kost: er passen veel bits op een kleine chip, en dus is de prijs per GB laag.\n2. Laag energieverbruik: belangrijk voor toestellen op batterij.\n3. Zeer vlug tegenover andere bestendige geheugens, vooral bij random lezen of schrijven: geen draaiende platen en geen bewegende kop.\n4. Betrouwbaar en compact: geen mechanische onderdelen, dus niets dat kan slijten of breken bij een val." },
  { v: "Waarom is flash ideaal voor draagbare toestellen?", a: "Door het lage energieverbruik.", o: "Flash: de doorbraak",
    uitleg: "Draagbare toestellen werken op een batterij. Hoe minder energie een onderdeel verbruikt, hoe langer de batterij meegaat.\n\nFlash verbruikt weinig energie:\n- er draait niets (een harde schijf moet zijn platen laten draaien en zijn kop bewegen);\n- zonder stroom blijven de gegevens bewaard, dus het geheugen hoeft niets te doen om ze te bewaren.\n\nDaarom zit flash in smartphones, tablets, laptops, camera's en smartwatches." },
  { v: "Waarin is flash vooral sneller dan andere bestendige geheugens?", a: "In random lezen of schrijven.", o: "Flash: de doorbraak",
    uitleg: "Random lezen of schrijven = kleine stukjes data op willekeurige plaatsen. Een harde schijf moet daarvoor telkens zijn kop verplaatsen en wachten tot de plaat draait. Flash heeft geen bewegende delen en is daar dus veel sneller in." },
  { v: "Waarom is flash betrouwbaarder dan een HDD?", a: "Er zijn geen mechanische onderdelen, en het is compact.", o: "Flash: de doorbraak",
    uitleg: "Een HDD (harde schijf) heeft bewegende delen: platen die duizenden keren per minuut draaien en een lees-/schrijfkop die er vlak boven zweeft. Een schok of val kan de kop tegen de plaat doen botsen en gegevens beschadigen.\n\nFlash heeft geen enkel bewegend onderdeel: alles gebeurt elektrisch in de chip. Daardoor:\n- kan het tegen schokken en trillingen;\n- slijt er niets mechanisch;\n- is het veel kleiner en lichter." },
  { v: "Welke beperking heeft flash nog altijd?", a: "Elke cel kan maar een beperkt aantal keer gewist worden.", o: "Flash: de doorbraak",
    uitleg: "Elke flashcel kan maar een beperkt aantal keer gewist worden (erase cycles). Bij elke wisbeurt slijt de cel een beetje, tot ze de lading niet meer goed vasthoudt.\n\nHoeveel keer hangt af van het type: SLC houdt het het langst vol, QLC het kortst.\n\nOplossingen in de praktijk:\n- wear leveling: de controller verdeelt het schrijven over alle cellen;\n- reservecellen: versleten cellen worden vervangen door reservecellen.\n\nVoor gewoon gebruik gaat een SSD daardoor jaren mee." },
  { v: "Geef 5 toestellen of producten waarin flash zit.", a: "Camera's, smartphones, printers, usb-sticks en SSD's.", o: "Flash: de doorbraak",
    uitleg: "Flash zit overal waar gegevens bewaard moeten blijven zonder stroom, in een klein formaat:\n- camera's: geheugenkaartje voor foto's;\n- smartphones: de volledige opslag (apps, foto's, het besturingssysteem);\n- printers: de software van de printer zelf (firmware);\n- usb-sticks;\n- SSD's: de snelle schijf in laptops en pc's.\n\nOok de BIOS/UEFI op het moederbord zit vandaag in flash." },
  { v: "Welke flashkaartjes gebruikt men vandaag vooral?", n: 2, a: "SD en microSD.", o: "Flash: de doorbraak",
    uitleg: "SD = Secure Digital: het standaardformaat voor geheugenkaartjes.\n- SD: ongeveer 32 x 24 mm, vooral in camera's.\n- microSD: veel kleiner (15 x 11 mm), vooral in smartphones, drones, actiecamera's en spelconsoles.\n\nMet een adapter kan je een microSD-kaartje in een SD-slot steken. Binnenin zit telkens flashgeheugen met een kleine controller." },
  { v: "Wear leveling", a: "Omdat een flashcel maar een beperkt aantal keer gewist kan worden, verspreidt de controller in een SSD of usb-stick het schrijven over alle cellen. Zo slijten ze ongeveer even snel en gaat het geheugen langer mee. Dat heet wear leveling.", o: "Flash: de doorbraak", extra: true },
  { v: "Wat is wear leveling bij flash?", a: "Het schrijven verdelen over alle cellen, zodat ze gelijkmatig slijten.", o: "Flash: de doorbraak",
    uitleg: "Elke flashcel kan maar een beperkt aantal keer gewist worden. Zou je altijd naar dezelfde cellen schrijven, dan zijn die snel versleten terwijl andere nog nieuw zijn.\n\nDe controller van een SSD of usb-stick houdt daarom bij hoe vaak elke cel gebruikt is, en schrijft nieuwe data naar de minst gebruikte cellen. Zo gaat het geheugen veel langer mee.\n\nElke keer dat je een cel wist, slijt ze een klein beetje. Na veel wisbeurten werkt ze niet meer. Bij gewoon gebruik duurt dat jaren." },
  { v: "Waarvoor staat SD bij een geheugenkaartje?", a: "Secure Digital.", o: "Flash: de doorbraak",
    uitleg: "SD en microSD zijn vandaag de meest gebruikte flashkaartjes, bv. in camera's, drones en sommige smartphones. microSD is de kleine versie.\n\nSD-kaartjes bestaan in verschillende capaciteiten, met een eigen naam:\n- SD: tot 2 GB;\n- SDHC (High Capacity): tot 32 GB;\n- SDXC (eXtended Capacity): tot 2 TB.\n\nBinnenin zit telkens flashgeheugen met een kleine controller." },
  { v: "Wat is flash, vergeleken met EEPROM?", a: "Een variant van EEPROM die niet per byte wist, maar per blok tegelijk.", o: "Flash: de doorbraak", extra: true,
    uitleg: "Daardoor zijn de cellen eenvoudiger en kleiner, en dus veel goedkoper en compacter." },
  { v: "Waar komt de naam 'flash' vandaan, en waarom maakte flash grote opslag betaalbaar?", a: "Flash wist een groot blok in één keer, snel: in een flits.\nOmdat hij per blok wist, zijn de cellen eenvoudiger en kleiner, en dus veel goedkoper en compacter. Zo werd grote opslag betaalbaar: usb-sticks, geheugenkaarten, SSD's.", o: "Flash: de doorbraak", extra: true,
    uitleg: "Flash is een variant van EEPROM die niet per byte, maar per blok wist." },
  { v: "Geef 4 toepassingen van flash.", a: "- usb-sticks, SD-kaarten en SSD's\n- opslag in smartphones en tablets\n- firmware en BIOS van moderne computers, routers en tv's\n- microcontrollers (de programmacode)", o: "Flash: de doorbraak", extra: true,
    uitleg: "Flash nam bijna alle toepassingen van EPROM over, en ook de opslag die vroeger op een harde schijf stond." },

  // ===== Flash: meer bits per cel (slide 20) =====
  { v: "Hoeveel bits per cel en hoeveel waarden heeft SLC?", a: "1 bit per cel, 2 waarden (2¹).", o: "Flash: meer bits per cel",
    uitleg: "Een flashcel bewaart gegevens als een hoeveelheid elektrische lading. De chip meet hoeveel lading er in de cel zit.\n\nSLC = Single-Level Cell: de cel kent 2 niveaus (2¹ = 2 waarden):\n- weinig lading = de ene waarde;\n- veel lading = de andere waarde.\n\nDat is 1 bit per cel. Omdat er maar 2 niveaus zijn, liggen ze ver uit elkaar. De chip kan ze snel en zeker onderscheiden, ook als de cel al wat versleten is." },
  { v: "Hoeveel bits per cel en hoeveel waarden hebben MLC en TLC?", a: "MLC: 2 bits, 4 waarden (2²).\nTLC: 3 bits, 8 waarden (2³).", o: "Flash: meer bits per cel", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s20_bitspercel.jpg",
    uitleg: "Hoe meer bits per cel, hoe meer niveaus van lading de cel moet kunnen onderscheiden:\n- MLC (Multi-Level Cell): 2 bits per cel = 2² = 4 niveaus (00, 01, 10, 11).\n- TLC (Triple-Level Cell): 3 bits per cel = 2³ = 8 niveaus.\n\nFormule: n bits per cel = 2ⁿ waarden.\n\nMeer bits per cel = meer opslag op dezelfde chip, dus goedkoper per GB. Maar de niveaus liggen dichter bij elkaar, dus de chip moet nauwkeuriger meten: dat is trager en de cel slijt sneller." },
  { v: "Hoeveel bits per cel en hoeveel waarden heeft QLC?", a: "4 bits per cel, 16 waarden (2⁴).", o: "Flash: meer bits per cel",
    uitleg: "QLC = Quad-Level Cell: 4 bits per cel = 2⁴ = 16 niveaus van lading.\n\n- Voordeel: de meeste opslag per chip, dus de laagste prijs per GB. Geschikt voor grote SSD's om veel bestanden op te bewaren.\n- Nadeel: 16 niveaus liggen heel dicht bij elkaar. Schrijven moet heel nauwkeurig gebeuren, dus het is traag, en de cel kan het minst aantal keer gewist worden." },
  { v: "Welk flashtype is het snelst en duurzaamst?", a: "SLC.", o: "Flash: meer bits per cel",
    uitleg: "SLC (1 bit per cel) is het snelst en het duurzaamst:\n- snel: met maar 2 niveaus moet de chip niet nauwkeurig meten of schrijven;\n- duurzaam: er is veel marge tussen de 2 niveaus, dus de cel blijft bruikbaar, ook als ze al wat versleten is. SLC kan het meeste aantal erase cycles aan.\n\nNadeel: maar 1 bit per cel, dus weinig opslag per chip en duur per GB. Daarom gebruikt men SLC vooral in industriële toestellen en servers waar betrouwbaarheid belangrijk is." },
  { v: "Welk flashtype heeft de meeste capaciteit, maar is het traagst?", a: "QLC.", o: "Flash: meer bits per cel",
    uitleg: "QLC (4 bits per cel) heeft de meeste capaciteit: op dezelfde chip passen 4x zoveel bits als bij SLC.\n\nHij is het traagst: de chip moet 16 verschillende niveaus van lading kunnen onderscheiden. Schrijven moet heel nauwkeurig, met controle na elke stap, en dat kost tijd. QLC slijt ook het snelst.\n\nDe regel: hoe meer bits per cel, hoe meer capaciteit, maar hoe trager en hoe minder duurzaam.\nSLC: snelst en duurzaamst, QLC: meeste capaciteit, traagst." },
  { v: "Welk type flash hoort bij 1, 2 en 3 op deze tekening?", a: "1 = SLC: 1 bit per cel\n2 = MLC: 2 bits per cel\n3 = TLC: 3 bits per cel", o: "Flash: meer bits per cel", img: "afbeeldingen/ITdeel2les6_optisch/l6_s20_bitspercel_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s20_bitspercel.jpg",
    uitleg: "Op de tekening zie je hoeveel niveaus van lading de cel moet onderscheiden:\n- 1 = SLC: 2 niveaus, 1 bit (0 of 1);\n- 2 = MLC: 4 niveaus, 2 bits (00, 01, 10, 11);\n- 3 = TLC: 8 niveaus, 3 bits (000 tot 111).\n\nHoe meer niveaus, hoe dichter ze bij elkaar liggen, hoe moeilijker om ze te onderscheiden. Daarom is TLC trager en minder duurzaam dan SLC.\n\nTel de niveaus: 2 (1 en 0), 4 (11 tot 00) en 8 (111 tot 000)." },
  { v: "Waar staan de afkortingen SLC, MLC, TLC en QLC voor?", a: "SLC = single-level cell\nMLC = multi-level cell\nTLC = triple-level cell\nQLC = quad-level cell", o: "Flash: meer bits per cel", extra: true },
  { v: "Waarvoor staan SLC, MLC, TLC en QLC, en wat bewaart een flashcel eigenlijk?", a: "Single-Level Cell, Multi-Level Cell, Triple-Level Cell en Quad-Level Cell.\nEen flashcel bewaart een hoeveelheid elektrische lading.", o: "Flash: meer bits per cel",
    uitleg: "Het aantal ladingsniveaus bepaalt hoeveel bits een cel bewaart:\n- SLC: 2 niveaus = 1 bit\n- MLC: 4 niveaus = 2 bits\n- TLC: 8 niveaus = 3 bits\n- QLC: 16 niveaus = 4 bits\n\nHoe meer niveaus, hoe kleiner het verschil ertussen, dus hoe nauwkeuriger je moet meten. Daarom is QLC trager en minder duurzaam dan SLC." },
  { v: "Hoe slaat een flashcel informatie op, en hoe leest de chip die?", a: "Als een hoeveelheid elektrische lading in de floating gate.\nBij het lezen meet de chip die lading (de spanning) en zet die om in bits.\nHoe meer ladingsniveaus je onderscheidt, hoe meer bits per cel.", o: "Flash: meer bits per cel", extra: true,
    uitleg: "In plaats van alleen \"lading of geen lading\" onderscheid je meerdere ladingsniveaus in één cel. Zo past er meer dan 1 bit in één cel." },
  { v: "Geef van SLC, MLC, TLC en QLC: voluit, bits per cel en ladingsniveaus.", a: "", o: "Flash: meer bits per cel", tabel: [["Type", "Voluit", "Bits per cel", "Ladingsniveaus"], ["SLC", "Single-Level Cell", "1", "2"], ["MLC", "Multi-Level Cell", "2", "4"], ["TLC", "Triple-Level Cell", "3", "8"], ["QLC", "Quad-Level Cell", "4", "16"]], extra: true,
    uitleg: "Het aantal niveaus is telkens 2^(aantal bits): 2¹ = 2, 2² = 4, 2³ = 8, 2⁴ = 16." },
  { v: "Hoeveel ladingsniveaus heeft een cel met n bits? Welke niveaus heeft MLC?", a: "2^n niveaus (2 tot de macht het aantal bits).\nMLC (2 bits) heeft 4 niveaus: 00, 01, 10 en 11.", o: "Flash: meer bits per cel", extra: true,
    uitleg: "SLC: 2 niveaus = 1 bit\nMLC: 4 niveaus = 2 bits\nTLC: 8 niveaus = 3 bits\nQLC: 16 niveaus = 4 bits" },
  { v: "Wat zijn de gevolgen van meer bits per cel?", a: "Voordeel: meer opslag op dezelfde chip, dus goedkoper per GB.\nMaar de niveaus liggen dichter bij elkaar. Daardoor:\n- moet het lezen en schrijven nauwkeuriger, dus trager;\n- zijn er sneller fouten, dus is er meer foutcorrectie nodig;\n- slijt de cel sneller: minder schrijfcycli.", o: "Flash: meer bits per cel", extra: true,
    uitleg: "Foutcorrectie = extra gegevens waarmee de controller leesfouten kan opsporen en herstellen.\n\nAantal schrijfcycli: SLC ongeveer 100.000, QLC maar ongeveer 1.000." },
  { v: "Hoeveel schrijfcycli halen SLC en QLC ongeveer?", a: "SLC: ongeveer 100.000.\nQLC: maar ongeveer 1.000.", o: "Flash: meer bits per cel", extra: true,
    uitleg: "Een schrijfcyclus = één keer wissen en opnieuw schrijven. Bij QLC liggen 16 niveaus dicht bij elkaar: een beetje slijtage is al genoeg om een niveau verkeerd te lezen. Bij SLC is er veel marge tussen de 2 niveaus." },
  { v: "Waar gebruikt men SLC, MLC, TLC en QLC?", a: "", o: "Flash: meer bits per cel", tabel: [["Type", "Gebruik"], ["SLC", "industriële en zakelijke toepassingen waar snelheid en levensduur belangrijk zijn: industrie, servers, auto's, plaatsen waar het lang en betrouwbaar moet werken"], ["MLC", "gewone SSD's; oudere of betere SSD's"], ["TLC", "gewone SSD's, het meest gebruikt: de meeste SSD's en smartphones"], ["QLC", "goedkope SSD's met veel capaciteit, vooral om op te slaan en te lezen"]], extra: true,
    uitleg: "Hoe belangrijker snelheid en duurzaamheid, hoe minder bits per cel. Hoe belangrijker veel opslag voor weinig geld, hoe meer bits per cel." },

  // ===== Geheugentypes op een rij (slide 21) =====
  { v: "Geef van SRAM, DRAM, SDRAM, ROM, PROM, EPROM, EEPROM en flash de categorie, hoe je wist, of het byte-alterable en volatile is, en het typisch gebruik.", a: "", o: "Geheugentypes op een rij",
    tabel: [["Type", "Category", "Wissen", "Byte-alterable", "Volatile", "Typisch gebruik"], ["SRAM", "read/write", "elektrisch", "ja", "ja", "cache in de processor"], ["DRAM", "read/write", "elektrisch", "ja", "ja", "werkgeheugen (vroeger)"], ["SDRAM", "read/write", "elektrisch", "ja", "ja", "werkgeheugen (nu, DDR)"], ["ROM", "read-only", "niet mogelijk", "nee", "nee", "grote reeksen toestellen"], ["PROM", "read-only", "niet mogelijk", "nee", "nee", "kleine reeksen"], ["EPROM", "read-mostly", "uv-licht", "nee", "nee", "prototypes"], ["EEPROM", "read-mostly", "elektrisch", "ja", "nee", "prototypes, instellingen"], ["Flash", "read/write", "elektrisch (blok)", "nee", "nee", "usb-stick, SSD, smartphone"]],
    uitleg: "Alle geheugentypes uit hoofdstuk 2 en 6 naast elkaar.\n\n- Byte-alterable = je kan één byte apart veranderen.\n- Volatile = de data is weg als de stroom uitvalt.\n- Read-mostly = je leest er vooral van en schrijft er maar af en toe (traag) naar.\n\nDe eerste 3 (SRAM, DRAM, SDRAM) zijn volatile: dat is het werkgeheugen en de cache. De andere 5 zijn non-volatile." },
  { v: "Welke geheugentypes uit de tabel zijn volatile?", n: 3, a: "SRAM, DRAM en SDRAM.", o: "Geheugentypes op een rij",
    uitleg: "Volatile = vluchtig: de inhoud verdwijnt zodra de stroom wegvalt.\n\nSRAM, DRAM en SDRAM zijn volatile. Het zijn werkgeheugens (RAM): ze moeten heel snel zijn en worden voortdurend overschreven. Ze bewaren de gegevens maar zolang de pc aanstaat.\n- SRAM houdt elke bit vast in een kleine schakeling van transistors.\n- DRAM en SDRAM houden elke bit vast als lading in een piepkleine condensator, die voortdurend ververst moet worden.\n\nAlle leesgeheugens (ROM, PROM, EPROM, EEPROM, flash) zijn non-volatile: ze bewaren hun inhoud zonder stroom." },
  { v: "Welke geheugentypes uit de tabel zijn read-only?", n: 2, a: "ROM en PROM.", o: "Geheugentypes op een rij",
    uitleg: "Read-only = alleen lezen. Na het programmeren kan de inhoud nooit meer veranderen:\n- ROM: de inhoud ligt vast vanaf de fabriek.\n- PROM: je schrijft er 1 keer op, en daarna ligt alles vast.\n\nBij beide is wissen niet mogelijk." },
  { v: "Welke geheugentypes uit de tabel zijn read-mostly?", n: 2, a: "EPROM en EEPROM.", o: "Geheugentypes op een rij",
    uitleg: "Read-mostly = vooral lezen. Je kan de inhoud wel wissen en opnieuw schrijven, maar dat gebeurt zelden, want het is traag of omslachtig:\n- EPROM: wissen met uv-licht, 20 tot 40 minuten, buiten het toestel.\n- EEPROM: elektrisch wissen in het toestel, maar schrijven blijft trager dan lezen en het aantal keer is beperkt.\n\nIn normaal gebruik lees je er dus vooral van. Schrijven doe je alleen bij een update of als een instelling verandert." },
  { v: "Hoe wis je SRAM, ROM, EPROM, EEPROM en flash volgens de tabel?", a: "SRAM: elektrisch.\nROM (en PROM): niet mogelijk.\nEPROM: uv-licht.\nEEPROM: elektrisch.\nFlash: elektrisch (per blok).", o: "Geheugentypes op een rij",
    uitleg: "Hoe je wist, hangt af van het type:\n- SRAM, DRAM en SDRAM: elektrisch. Je overschrijft gewoon, en zonder stroom is alles toch weg.\n- ROM en PROM: niet mogelijk. De inhoud ligt vast.\n- EPROM: met uv-licht, door het venster uit kwartskristal.\n- EEPROM: elektrisch, per byte, in het toestel zelf.\n- Flash: elektrisch, maar per blok.\n\nDe evolutie gaat van niet wissen (ROM, PROM), over uv-licht (EPROM), naar elektrisch wissen (EEPROM, flash)." },
  { v: "Welke geheugentypes zijn byte-alterable?", n: 4, a: "SRAM, DRAM, SDRAM en EEPROM.", o: "Geheugentypes op een rij",
    uitleg: "Byte-alterable = je kan één enkele byte veranderen zonder de rest aan te raken.\n\n- SRAM, DRAM en SDRAM: ja, je schrijft gewoon een nieuwe waarde op die plek.\n- EEPROM (full-featured): ja, je kan per byte wissen en herschrijven.\n\nNiet byte-alterable:\n- ROM en PROM: je kan niets veranderen.\n- EPROM: je wist altijd de hele chip.\n- Flash: je wist altijd een heel blok." },
  { v: "Is flash byte-alterable? Waarom?", a: "Nee: flash wist per blok.", o: "Geheugentypes op een rij",
    uitleg: "Flash wist per blok, niet per byte. Een blok bevat heel veel bytes.\n\nWil je in flash één byte veranderen, dan moet de controller:\n1. het hele blok lezen;\n2. het blok wissen;\n3. het blok opnieuw schrijven met die ene byte aangepast.\n\nDaarom is flash niet byte-alterable. In de praktijk schrijft de controller de nieuwe gegevens meestal naar een ander, al gewist blok, en ruimt hij het oude blok later op." },
  { v: "Wat is het typisch gebruik van SRAM, DRAM en SDRAM?", a: "SRAM: cache in de processor.\nDRAM: werkgeheugen (vroeger).\nSDRAM: werkgeheugen (nu, DDR).", o: "Geheugentypes op een rij",
    uitleg: "Werkgeheugens, allemaal volatile, read/write en byte-alterable:\n- SRAM (statisch RAM): het snelst en het duurst, met weinig capaciteit. Gebruikt als cache in de processor (L1, L2, L3).\n- DRAM (dynamisch RAM): goedkoper en met meer capaciteit, maar moet voortdurend ververst worden. Was vroeger het werkgeheugen.\n- SDRAM (synchroon DRAM): DRAM dat gelijk loopt met de klok van het systeem. Vandaag het werkgeheugen, in de vorm van DDR4 en DDR5.\n\nMeer hierover in hoofdstuk II.2 Werkgeheugen." },
  { v: "Wat is het typisch gebruik van ROM en PROM?", a: "ROM: grote reeksen toestellen.\nPROM: kleine reeksen.", o: "Geheugentypes op een rij",
    uitleg: "ROM: de inhoud zit in de chip vanaf de fabriek. Een eigen ROM laten maken kost veel bij de start, maar per chip weinig. Dat loont alleen bij grote reeksen identieke toestellen, waarvan de software zeker niet meer verandert.\n\nPROM: een standaard lege chip die je zelf 1 keer programmeert. Geen dure productie nodig, dus geschikt voor kleine reeksen en prototypes." },
  { v: "Wat is het typisch gebruik van EPROM, EEPROM en flash?", a: "EPROM: prototypes.\nEEPROM: prototypes, instellingen.\nFlash: usb-stick, SSD, smartphone.", o: "Geheugentypes op een rij",
    uitleg: "EPROM: prototypes. Je kan hem wissen met uv-licht en opnieuw programmeren, handig zolang de software nog verandert.\n\nEEPROM: prototypes en instellingen. Hij wist elektrisch, in het toestel zelf. Daardoor kan een toestel zijn eigen instellingen bewaren, bijvoorbeeld de instellingen van een BIOS, een router of een printer.\n\nFlash: usb-stick, SSD, smartphone. Goedkoop, veel capaciteit, snel en zuinig: de standaard voor opslag vandaag." },
  { v: "Welke category heeft flash volgens de tabel?", a: "Read/write.", o: "Geheugentypes op een rij",
    uitleg: "Flash staat in de tabel als read/write, net als de werkgeheugens. Je kan er dus vrij in lezen en schrijven, en dat doe je voortdurend: foto's opslaan, bestanden kopiëren, apps installeren.\n\nHet verschil met de werkgeheugens:\n- flash is non-volatile: de gegevens blijven bewaard zonder stroom;\n- flash wist per blok, dus hij is niet byte-alterable.\n\nEPROM en EEPROM zijn read-mostly: daar schrijf je zelden." },

  // ===== SSD's: flash als schijf (slide 22) =====
  { v: "Vergelijk een SSD en een HDD: prijs per GB, opstarten, geluid, energie, schokken en typisch gebruik.", a: "", o: "SSD's: flash als schijf",
    tabel: [["", "SSD", "HDD"], ["Prijs per GB", "hoger", "lager"], ["Opstarten en laden", "snel: geen draaiende onderdelen", "trager: de platen draaien, de kop beweegt"], ["Geluid", "geruisloos", "hoorbaar"], ["Energie en warmte", "laag", "hoger"], ["Schokken, temperatuur", "betrouwbaar", "gevoeliger: bewegende delen"], ["Typisch gebruik", "systeemschijf", "veel opslag voor weinig geld"]],
    uitleg: "Een SSD (solid state drive) bestaat uit NAND-flash, vaak met een cache op basis van DRAM. Solid state betekent: zonder bewegende delen. De DRAM-cache is een stukje snel werkgeheugen in de SSD, waarin hij bijvoorbeeld bijhoudt waar alle data staat.\n\nDaarom zet men het besturingssysteem vaak op een SSD (snel opstarten) en grote hoeveelheden bestanden op een HDD (goedkoop)." },
  { v: "Waarvoor staat SSD?", a: "Solid state drive.", o: "SSD's: flash als schijf",
    uitleg: "SSD = Solid State Drive.\n\n- Solid state: zonder bewegende onderdelen. Alles gebeurt elektrisch in chips.\n- Drive: een opslagschijf, zoals een harde schijf.\n\nDe naam zegt dat het een schijf is zonder draaiende platen: een SSD vervangt de harde schijf (HDD), maar is binnenin alleen flashgeheugen met een controller." },
  { v: "Uit welk geheugen bestaat een SSD?", a: "NAND-flash, vaak met een cache op basis van DRAM.", o: "SSD's: flash als schijf",
    uitleg: "Een SSD bestaat uit:\n- NAND-flash: de chips waarin je gegevens bewaard worden. NAND is het type flash dat het meest compact en het goedkoopst is per GB.\n- een controller: de chip die alles regelt (wear leveling, versleten cellen vervangen, foutcorrectie);\n- vaak een cache op basis van DRAM: een klein, snel werkgeheugen. Daarin houdt de controller onder meer bij waar elk bestand in de flash staat. Dat maakt de SSD sneller.\n\nDe flash bewaart de gegevens zonder stroom. De DRAM-cache is volatile, maar bevat alleen hulpgegevens." },
  { v: "Wat is goedkoper per GB: een SSD of een HDD?", a: "Een HDD. Een SSD heeft een hogere prijs per GB.", o: "SSD's: flash als schijf",
    uitleg: "Een HDD is goedkoper per GB. Een harde schijf zet veel gegevens op magnetische platen, en grotere platen of meer platen kosten weinig extra.\n\nBij een SSD heb je voor meer GB meer flashchips nodig, en die zijn duurder per GB.\n\nDaarom:\n- veel opslag voor weinig geld: HDD;\n- snelheid: SSD." },
  { v: "Waarom start een computer met een SSD sneller op dan met een HDD?", a: "Een SSD heeft geen draaiende onderdelen. Bij een HDD moeten de platen draaien en de kop bewegen.", o: "SSD's: flash als schijf",
    uitleg: "Opstarten = het besturingssysteem en programma's inladen. Daarvoor moeten duizenden kleine bestanden gelezen worden, verspreid over de schijf.\n\n- HDD: voor elk bestand moet de kop naar de juiste plaats bewegen en wachten tot de draaiende plaat het juiste stuk onder de kop brengt. Dat duurt telkens een paar milliseconden.\n- SSD: geen draaiende onderdelen. Elk stuk flash is meteen bereikbaar, in minder dan een tiende milliseconde.\n\nBij random lezen (veel kleine stukjes op verschillende plaatsen) is een SSD daardoor vele keren sneller." },
  { v: "Vergelijk SSD en HDD op geluid en op energie en warmte.", a: "Geluid: SSD geruisloos, HDD hoorbaar.\nEnergie en warmte: SSD laag, HDD hoger.", o: "SSD's: flash als schijf",
    uitleg: "Geluid:\n- SSD: geruisloos, er beweegt niets.\n- HDD: hoorbaar, je hoort de platen draaien en de kop tikken.\n\nEnergie en warmte:\n- SSD: weinig energie, dus weinig warmte. Belangrijk voor de batterij van een laptop.\n- HDD: hoger verbruik, omdat een motor de platen voortdurend laat draaien." },
  { v: "Welke is gevoeliger voor schokken en temperatuur: SSD of HDD? Waarom?", a: "De HDD: die heeft bewegende delen. Een SSD is betrouwbaar.", o: "SSD's: flash als schijf",
    uitleg: "De HDD is gevoeliger. Hij heeft bewegende delen:\n- platen die duizenden keren per minuut draaien;\n- een lees-/schrijfkop die vlak boven de plaat zweeft.\n\nEen schok kan de kop tegen de plaat doen slaan: gegevens beschadigd of de schijf kapot. Hitte en kou hebben ook invloed op de mechanische delen.\n\nEen SSD heeft geen bewegende delen en is daardoor betrouwbaar bij schokken, trillingen en temperatuurverschillen. Ideaal voor laptops die meegenomen worden." },
  { v: "Wat is het typisch gebruik van een SSD en van een HDD?", a: "SSD: systeemschijf.\nHDD: veel opslag voor weinig geld.", o: "SSD's: flash als schijf",
    uitleg: "SSD = systeemschijf: daarop staan het besturingssysteem en de programma's. Die moeten snel geladen worden, en daar maakt een SSD het grootste verschil.\n\nHDD = veel opslag voor weinig geld: foto's, video's, back-ups en archieven. Die heb je niet voortdurend nodig, en daar telt de prijs per GB meer dan de snelheid." },
  { v: "Waarom combineert men vaak een SSD en een HDD in één computer?", a: "De SSD voor snelheid (besturingssysteem en programma's), de HDD voor veel goedkope opslag (foto's, films).", o: "SSD's: flash als schijf",
    uitleg: "Een SSD is veel sneller, maar per GB duurder. Een HDD is trager, maar je krijgt veel opslag voor weinig geld.\n\nDoor beide te combineren, start de pc snel op (van de SSD) en heb je toch veel ruimte voor grote bestanden (op de HDD)." },

  // ===== Form factor: 2,5 inch (slide 23) =====
  { v: "Welke interface gebruikt een 2,5 inch SSD?", a: "Enkel SATA.", o: "Form factor: 2,5 inch",
    uitleg: "SATA (Serial ATA) is de aansluiting (interface) waarlangs de SSD met het moederbord praat.\n\n- Het is dezelfde aansluiting als bij een harde schijf: een datakabel naar het moederbord en een stroomkabel van de voeding.\n- SATA haalt maximaal ongeveer 550 MB/s. Een SATA-SSD is daardoor veel sneller dan een HDD, maar trager dan een SSD via PCIe (NVMe).\n\nEen 2,5 inch SSD gebruikt enkel SATA.\n\nSATA is de aansluiting (interface) waarlangs de SSD met het moederbord praat." },
  { v: "In welke toestellen gebruik je een 2,5 inch SATA-SSD?", a: "In desktops en laptops.", o: "Form factor: 2,5 inch",
    uitleg: "Een 2,5 inch SATA-SSD past in:\n- desktops: in een schijfplaats in de kast, met een datakabel en een stroomkabel;\n- laptops: in de plaats van de oude 2,5 inch harde schijf.\n\nHij wordt vooral gebruikt om een oudere pc of laptop sneller te maken: je vervangt de harde schijf door een SSD van hetzelfde formaat." },
  { v: "Waarom is een 2,5 inch SSD een rechtstreekse vervanger van een harde schijf?", a: "Hij heeft dezelfde vorm als een 2,5 inch harde schijf.", o: "Form factor: 2,5 inch",
    uitleg: "Form factor = de vorm en de afmetingen van een onderdeel. Een 2,5 inch SSD past op exact dezelfde plaats en met dezelfde kabels als een 2,5 inch harde schijf. Je kan een oude harde schijf dus gewoon vervangen door een SSD.", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s23_sata.jpg" },
  { v: "Welke form factor zie je op deze foto (1)?", a: "1 = 2,5 inch SATA-SSD.", o: "Form factor: 2,5 inch", img: "afbeeldingen/ITdeel2les6_optisch/l6_s23_sata_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s23_sata.jpg",
    uitleg: "1 = 2,5 inch SATA-SSD. Herkenbaar aan:\n- een plat, rechthoekig doosje van ongeveer 10 x 7 cm, vaak uit metaal of plastic;\n- aan de korte kant twee aansluitingen: een kleine voor data (SATA) en een bredere voor stroom.\n\nDat is precies dezelfde vorm en dezelfde aansluiting als een 2,5 inch harde schijf voor laptops." },
  { v: "Wat is SATA?", a: "SATA (Serial ATA) is de standaardaansluiting voor harde schijven en 2,5 inch SSD's. Er gaan twee kabels naar het toestel: een datakabel en een stroomkabel.", o: "Form factor: 2,5 inch", extra: true },

  // ===== Form factor: M.2 (slide 24) =====
  { v: "Welke interfaces kan een M.2-SSD gebruiken?", a: "SATA of PCIe (NVMe).", o: "Form factor: M.2",
    uitleg: "Een M.2-SSD kan op twee manieren met de pc praten:\n- SATA: even snel als een 2,5 inch SATA-SSD (tot ongeveer 550 MB/s);\n- PCIe met NVMe: rechtstreeks via de PCIe-bus, vele keren sneller (enkele GB/s).\n\nBeide zien er bijna hetzelfde uit. Het slot op het moederbord moet de juiste interface ondersteunen. Kijk dus altijd in de specificaties of het om een SATA- of een NVMe-SSD gaat." },
  { v: "Zegt M.2 iets over de snelheid van een SSD?", a: "Nee: M.2 is een form factor, geen snelheid.", o: "Form factor: M.2",
    uitleg: "'Geen snelheid': M.2 zegt alleen iets over de vorm. Een M.2-SSD kan via SATA werken (even snel als een 2,5 inch SSD) of via PCIe/NVMe (veel sneller). Kijk dus altijd welke interface hij gebruikt.", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s24_m2.jpg" },
  { v: "Hoe wordt een M.2-SSD aangesloten?", a: "Rechtstreeks op het moederbord, zonder kabels.", o: "Form factor: M.2",
    uitleg: "Een M.2-SSD is een klein, plat printplaatje dat je rechtstreeks in een slot op het moederbord steekt en vastschroeft.\n\nHet slot heeft een kleine uitsparing (key) op de aansluiting, zodat je de SSD maar op één manier kan insteken.\n\nWerkwijze: je steekt de SSD schuin in het slot, drukt hem plat en schroeft hem aan het andere uiteinde vast met één schroefje.\n\nOmdat er geen data- en stroomkabels nodig zijn, gaan zowel de gegevens als de stroom via het moederbord." },
  { v: "In welke toestellen vind je M.2?", a: "In laptops en desktops.", o: "Form factor: M.2",
    uitleg: "M.2 zit in laptops en desktops.\n\n- In laptops is M.2 de standaard: het kleine, platte formaat zonder kabels spaart veel ruimte.\n- Op moderne moederborden van desktops zitten meestal een of meer M.2-slots.\n\nOmdat er geen kabels nodig zijn, zijn ze snel en eenvoudig te installeren: steken en vastschroeven." },
  { v: "Wat betekent 2280 bij een M.2-SSD?", a: "22 mm breed en 80 mm lang: de lengte staat in de naam.", o: "Form factor: M.2",
    uitleg: "De vier cijfers zijn de afmetingen van het printplaatje in millimeter:\n- de eerste 2 cijfers = de breedte: 22 mm;\n- de volgende cijfers = de lengte: 80 mm.\n\n2280 = 22 mm breed en 80 mm lang: het meest gebruikte formaat. Andere lengtes: 2242 (42 mm), 2260 (60 mm) en 22110 (110 mm).\n\nHet moederbord heeft schroefposities op verschillende afstanden, zodat je verschillende lengtes kan vastschroeven." },
  { v: "Welke lengtes kan je in de M.2-slots op deze foto vastschroeven?", n: 4, a: "2242, 2260, 2280 en 22110.", o: "Form factor: M.2", img: "afbeeldingen/ITdeel2les6_optisch/l6_s24_m2.jpg",
    uitleg: "Alle M.2-modules zijn 22 mm breed; de laatste cijfers zijn de lengte: 42, 60, 80 of 110 mm.\n\nDe foto toont twee M.2-slots, met schroefposities voor 2242, 2260, 2280 en 22110." },
  { v: "Is M.2 een small form factor?", a: "Ja.", o: "Form factor: M.2",
    uitleg: "Ja. Small form factor = een klein formaat.\n\nEen M.2-SSD is een klein, plat printplaatje van 22 mm breed, zonder behuizing en zonder kabels. Hij neemt veel minder plaats in dan een 2,5 inch SSD. Daarom is M.2 de standaard in dunne laptops en compacte pc's." },
  { v: "Wat is NVMe?", a: "NVMe (Non-Volatile Memory Express) is een manier van communiceren die speciaal voor flash gemaakt is en over PCIe loopt. Een NVMe-SSD is meerdere keren sneller dan een SATA-SSD.", o: "Form factor: M.2", extra: true },

  // ===== Form factors naast elkaar (slide 25) =====
  { v: "Welke 3 vormen van SSD zie je naast elkaar op deze foto?", a: "2,5 inch SATA, M.2 en PCIe add-in card.", o: "Form factors naast elkaar", img: "afbeeldingen/ITdeel2les6_optisch/l6_s25_formfactors.jpg",
    uitleg: "- 2,5 inch SATA-SSD: zelfde vorm als een 2,5 inch harde schijf, met een kabel aangesloten.\n- M.2: een klein plat kaartje, rechtstreeks op het moederbord.\n- PCIe add-in card: een SSD op een insteekkaart die je in een PCIe-slot steekt, zoals een grafische kaart." },
  { v: "Welke form factors staan op plaats 1, 2 en 3?", a: "1 = 2,5 inch SATA\n2 = M.2\n3 = PCIe add-in card", o: "Form factors naast elkaar", img: "afbeeldingen/ITdeel2les6_optisch/l6_s25_formfactors_vraag.jpg", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s25_formfactors.jpg",
    uitleg: "1 = 2,5 inch SATA: een plat doosje met een SATA-aansluiting en een stroomaansluiting. Gaat met kabels naar het moederbord en de voeding.\n2 = M.2: een klein, plat printplaatje zonder behuizing. Gaat rechtstreeks in een slot op het moederbord.\n3 = PCIe add-in card: een insteekkaart, vaak met een koelplaat. Gaat in een PCIe-slot van het moederbord, zoals een grafische kaart." },
  { v: "Wat is een PCIe add-in card als SSD?", a: "Een SSD op een insteekkaart die rechtstreeks in een PCIe-slot van het moederbord gaat, zoals een grafische kaart.", o: "Form factors naast elkaar",
    uitleg: "Een PCIe add-in card gebruikt altijd PCIe en heeft geen kabels nodig. Je vindt ze vooral in desktops en servers.\n\nDe SSD zit op een printkaart met een PCIe-aansluiting onderaan. Vaak zit er een koelplaat op, omdat heel snelle SSD's warm worden.\n\nHet voordeel: een PCIe-slot heeft veel lanes (bijvoorbeeld x4, x8 of x16). Zo kan een add-in card heel hoge snelheden halen, of meerdere SSD's op één kaart dragen." },

  // ===== U.2: SSD's voor servers (slide 26) =====
  { v: "Welk formaat heeft een U.2-SSD?", a: "Het 2,5 inch-formaat, in een behuizing (vaak in de vorm van passieve koeling).", o: "U.2: SSD's voor servers", imgAntwoord: "afbeeldingen/ITdeel2les6_optisch/l6_s26_u2.jpg",
    uitleg: "U.2 heeft hetzelfde formaat als een 2,5 inch schijf, maar in een dikkere, stevige behuizing, vaak uit metaal met koelribben (passieve koeling).\n\nZo past hij in de schijfplaatsen van servers, waar schijven naast elkaar in een rek zitten en vaak vervangen kunnen worden terwijl de server blijft draaien.\n\nBinnenin zit een snelle NVMe-SSD." },
  { v: "Welke interface gebruikt U.2?", a: "Enkel PCIe.", o: "U.2: SSD's voor servers",
    uitleg: "U.2 gebruikt enkel PCIe (met NVMe), nooit SATA.\n\nPCIe is veel sneller dan SATA. Servers en werkstations hebben die snelheid nodig, omdat veel gebruikers of zware programma's tegelijk gegevens lezen en schrijven.\n\nHet verschil met een 2,5 inch SATA-SSD: dezelfde breedte en lengte, maar een andere aansluiting en veel sneller." },
  { v: "Waar vind je U.2-SSD's?", a: "In werkstations en servers.", o: "U.2: SSD's voor servers",
    uitleg: "U.2-SSD's vind je in werkstations en servers:\n- werkstations: krachtige pc's voor professioneel werk, zoals video bewerken of 3D;\n- servers: computers die diensten leveren aan veel gebruikers, zoals databanken of websites.\n\nDaar is veel snelle opslag nodig die dag en nacht draait. Ze zijn duurder dan gewone SSD's en zitten bijna nooit in een gewone pc." },
  { v: "Hoe wordt een U.2-SSD aangesloten?", a: "Via kabels.", o: "U.2: SSD's voor servers",
    uitleg: "Een U.2-SSD wordt via kabels aangesloten, met een eigen U.2-connector die data en stroom samen doorgeeft.\n\nIn een server zit hij meestal in een schijfplaats aan de voorkant. Van daaruit lopen kabels naar het moederbord of naar een controllerkaart. Zo kan je een schijf vervangen zonder de server open te maken.\n\nEen M.2-SSD en een PCIe add-in card hebben geen kabels nodig." },
  { v: "Welk soort SSD zie je op deze foto?", a: "U.2-SSD's: het 2,5 inch-formaat in een behuizing met passieve koeling.", o: "U.2: SSD's voor servers", img: "afbeeldingen/ITdeel2les6_optisch/l6_s26_u2.jpg",
    uitleg: "Op de foto zie je U.2-SSD's:\n- het 2,5 inch-formaat;\n- in een dikke, metalen behuizing met ribbels: dat is de passieve koeling;\n- aan de korte kant een U.2-connector voor de kabel.\n\nJe herkent ze aan de stevige metalen behuizing met koelribben. Een 2,5 inch SATA-SSD is dunner en heeft een gladde behuizing met twee aparte aansluitingen." },
  { v: "Wat is passieve koeling bij een U.2-SSD?", a: "Koeling zonder ventilator, via een metalen behuizing met koelribben.", o: "U.2: SSD's voor servers",
    uitleg: "De metalen behuizing neemt de warmte van de chips op en geeft ze via de ribben af aan de lucht. Er draait niets: daarom 'passief'.\n\nU.2-SSD's zijn snel (PCIe) en worden daardoor warm; in servers zorgt de luchtstroom van de serverventilatoren voor de rest.\n\nEen U.2-SSD ziet eruit als een 2,5 inch SSD, maar is dikker en zit in een metalen behuizing met koelribben. Die ribben voeren de warmte af zonder ventilator: dat heet passieve koeling." },

  // ===== Form factors vergeleken (slide 27) =====
  { v: "Vergelijk de 4 vormen van SSD: interface, kabels en waar je ze vindt.", a: "", o: "Form factors vergeleken",
    tabel: [["Form factor", "Interface", "Kabels", "Waar je het vindt"], ["2,5 inch", "SATA", "ja, data en stroom", "desktop en laptop, vervangt een 2,5 inch harde schijf"], ["M.2", "SATA of PCIe (NVMe)", "nee, op het moederbord", "laptop en desktop"], ["U.2", "PCIe", "ja", "werkstations en servers"], ["PCIe add-in card", "PCIe", "nee, in een PCIe-slot", "desktop en servers"]],
    uitleg: "- 2,5 inch is altijd SATA: maximaal ongeveer 550 MB/s.\n- M.2 kan SATA of PCIe (NVMe) zijn: de vorm zegt niets over de snelheid, kijk naar de specificaties.\n- U.2 en de PCIe add-in card zijn altijd PCIe." },
  { v: "Geef de 4 form factors van SSD's uit de cursus.", a: "2,5 inch, M.2, U.2 en PCIe add-in card.", o: "Form factors vergeleken",
    uitleg: "De 4 form factors van SSD's:\n1. 2,5 inch: SATA, met kabels, vervangt een harde schijf.\n2. M.2: SATA of PCIe (NVMe), klein printplaatje rechtstreeks op het moederbord.\n3. U.2: PCIe, 2,5 inch in een behuizing met koeling, met kabels, voor servers.\n4. PCIe add-in card: PCIe, insteekkaart in een PCIe-slot.\n\nForm factor = de vorm en de grootte, niet de snelheid. De snelheid hangt af van de interface (SATA of PCIe)." },
  { v: "Welke form factors gebruiken enkel PCIe?", n: 2, a: "U.2 en PCIe add-in card.", o: "Form factors vergeleken",
    uitleg: "Enkel PCIe:\n- U.2: in servers en werkstations, via kabels;\n- PCIe add-in card: in een PCIe-slot.\n\nEnkel SATA: de 2,5 inch SSD.\nSATA of PCIe: M.2.\n\nPCIe gaat rechtstreeks naar de processor of de chipset, en is daardoor veel sneller dan SATA." },
  { v: "Welke form factor kan zowel SATA als PCIe (NVMe) gebruiken?", a: "M.2.", o: "Form factors vergeleken",
    uitleg: "M.2 kan zowel SATA als PCIe (NVMe) gebruiken. Dat zie je niet altijd aan de buitenkant:\n- M.2 SATA: tot ongeveer 550 MB/s, even snel als een 2,5 inch SSD;\n- M.2 NVMe: via PCIe, vele keren sneller.\n\nDaarom zegt de cursus: M.2 is een form factor, geen snelheid." },
  { v: "Welke form factors hebben kabels nodig?", n: 2, a: "2,5 inch (data en stroom) en U.2.", o: "Form factors vergeleken",
    uitleg: "Met kabels:\n- 2,5 inch: twee kabels, een datakabel (SATA) naar het moederbord en een stroomkabel van de voeding;\n- U.2: kabels naar het moederbord of een controller.\n\nZonder kabels:\n- M.2: rechtstreeks in een slot op het moederbord;\n- PCIe add-in card: rechtstreeks in een PCIe-slot.\n\nZonder kabels is de installatie eenvoudiger en neemt de SSD minder plaats in." },
  { v: "Waar zit een M.2-SSD, en waar een PCIe add-in card?", a: "M.2: op het moederbord.\nPCIe add-in card: in een PCIe-slot.", o: "Form factors vergeleken",
    uitleg: "M.2: rechtstreeks in een klein slot op het moederbord, plat vastgeschroefd. Vaak zit er een koelplaatje over.\n\nPCIe add-in card: in een PCIe-slot, de lange sleuven op het moederbord waar ook de grafische kaart in gaat. De kaart staat rechtop en wordt aan de achterkant van de kast vastgeschroefd." },
  { v: "Waar vind je een PCIe add-in card?", a: "In desktops en servers.", o: "Form factors vergeleken",
    uitleg: "Een PCIe add-in card vind je in desktops en servers.\n\n- Een laptop heeft geen PCIe-slots voor insteekkaarten, dus daar kan hij niet in.\n- In een desktop of server heb je de ruimte en de slots.\n\nEen add-in card wordt vooral gebruikt voor heel snelle opslag of als er geen M.2-slot meer vrij is." },
  { v: "Welke form factor vervangt een 2,5 inch harde schijf?", a: "De 2,5 inch SSD (SATA).", o: "Form factors vergeleken",
    uitleg: "De 2,5 inch SATA-SSD vervangt een 2,5 inch harde schijf. Hij heeft:\n- dezelfde vorm en grootte;\n- dezelfde aansluitingen (SATA-data en SATA-stroom);\n- dezelfde schroefgaten.\n\nJe haalt de harde schijf eruit en zet de SSD op dezelfde plaats. Dat is de eenvoudigste manier om een oudere laptop of pc veel sneller te maken." },
];

